# Static weight matrix mapping severity levels to consensus impact values
_SEVERITY_WEIGHTS: Final[tuple[int, ...]] = (0, 1, 3, 8, 20)
_SEVERITY_WEIGHT_MAP: Final[Dict[int, int]] = {
    0: 0,   # INFO
    1: 1,   # LOW
    2: 3,   # MEDIUM
    3: 8,   # HIGH
    4: 20,  # CRITICAL
}


def _safe_format_utc_timestamp() -> str:
    """Defensive UTC timestamp retrieval with deterministic fallback."""
    try:
        ts = format_utc_timestamp()
        if isinstance(ts, str) and ts:
            return ts
    except Exception:
        pass
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


class DiagnosticSeverity(IntEnum):
    """Integrity levels for diagnostic weighting and consensus prioritization."""
    INFO = 0
    LOW = 1
    MEDIUM = 2
    HIGH = 3
    CRITICAL = 4

    @property
    def weight(self) -> int:
        """Returns the impact weight for the Integrity Score calculation."""
        return _SEVERITY_WEIGHT_MAP.get(self.value, 1)

    @classmethod
    def from_any(cls, value: Any, default: DiagnosticSeverity = MEDIUM) -> DiagnosticSeverity:
        """Defensively coerces arbitrary values into a valid DiagnosticSeverity member."""
        if isinstance(value, cls):
            return value
        if isinstance(value, bool):
            return cls.HIGH if not value else cls.INFO
        if hasattr(value, "value"):
            try:
                candidate = cls.from_any(value.value, default=default)
                if isinstance(candidate, cls):
                    return candidate
            except Exception:
                pass
        if hasattr(value, "name"):
            try:
                name_str = str(value.name).strip().upper()
                if name_str in cls.__members__:
                    return cls[name_str]
            except Exception:
                pass
        if isinstance(value, (int, float)):
            try:
                int_val = int(value)
                return cls(int_val)
            except (ValueError, OverflowError):
                pass
        elif isinstance(value, str):
            normalized = value.strip().upper()
            if normalized in cls.__members__:
                return cls[normalized]
            if normalized.isdigit() or (normalized.startswith(('-', '+')) and normalized[1:].isdigit()):
                try:
                    int_val = int(normalized)
                    return cls(int_val)
                except (ValueError, OverflowError):
                    pass
        return default


@dataclass(frozen=True, slots=True)
class DiagnosticResult:
    """
    Immutable diagnostic check result payload.
    Adheres to Zero-Leak architectural pillars via slotting and immutable state.
    """
    passed: bool
    message: str
    severity: DiagnosticSeverity = DiagnosticSeverity.MEDIUM
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        """Enforces structural defensive copying and type coercion on parameters."""
        if not isinstance(self.passed, bool):
            object.__setattr__(self, "passed", bool(self.passed))
        if not isinstance(self.message, str):
            object.__setattr__(self, "message", str(self.message) if self.message is not None else "")
        if not isinstance(self.severity, DiagnosticSeverity):
            object.__setattr__(
                self,
                "severity",
                DiagnosticSeverity.from_any(self.severity, DiagnosticSeverity.MEDIUM),
            )
        meta = self.metadata
        if type(meta) is dict:
            try:
                object.__setattr__(self, "metadata", dict(meta))
            except Exception:
                object.__setattr__(self, "metadata", {"raw_metadata": str(meta)})
        elif isinstance(meta, Mapping):
            try:
                object.__setattr__(self, "metadata", dict(meta))
            except Exception:
                object.__setattr__(self, "metadata", {"raw_metadata": str(meta)})
        else:
            object.__setattr__(self, "metadata", {"raw_metadata": str(meta) if meta is not None else {}})


class DiagnosticCheck(Protocol):
    """Structural subtyping for diagnostic callables."""
    def __call__(self) -> Union[DiagnosticResult, bool, Dict[str, Any], Any]: ...


class DiagnosticEngine:
    """
    Sovereign high-integrity diagnostic engine (Tessera-OS Core).
    Implements DARLEK CAAN evolution protocols and parallelized telemetry synthesis.
    """

    __slots__ = ("_checks", "_lock", "_executor", "_default_timeout", "_is_shutdown", "__weakref__")

    def __init__(self, default_timeout: float = 5.0, max_workers: int = 8) -> None:
        self._checks: Dict[str, DiagnosticCheck] = {}
        self._lock = threading.RLock()

        try:
            parsed_timeout = float(default_timeout)
            if parsed_timeout != parsed_timeout or parsed_timeout <= 0.0:
                parsed_timeout = 5.0
        except (ValueError, TypeError):
            parsed_timeout = 5.0
        self._default_timeout: float = max(0.1, parsed_timeout)

        try:
            parsed_workers = int(max_workers)
        except (ValueError, TypeError):
            parsed_workers = 8
        clamped_workers = max(1, min(parsed_workers, 128))

        self._is_shutdown: bool = False
        self._executor: concurrent.futures.ThreadPoolExecutor = concurrent.futures.ThreadPoolExecutor(
            max_workers=clamped_workers,
            thread_name_prefix="GenesisDiagnostic"
        )
        try:
            atexit.register(self._cleanup_atexit)
        except Exception:
            pass

    def __enter__(self) -> Self:
        return self

    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        self.shutdown(wait=True)

    def _cleanup_atexit(self) -> None:
        """Defensive atexit handler ensuring ThreadPoolExecutor leak prevention."""
        try:
            self.shutdown(wait=False)
        except Exception:
            pass

    def register(self, name: str, check_fn: DiagnosticCheck) -> Self:
        """
        Registers a module to the Sovereign Registry.
        Enforces strict signature validation and state safety checks.
        """
        if not name or not isinstance(name, str) or not name.strip():
            raise ValueError("Registry Error: Module identifier must be a non-empty string.")

        if not callable(check_fn):
            raise TypeError(f"Registry Error: '{name}' must provide a callable check_fn.")

        with self._lock:
            if self._is_shutdown:
                raise RuntimeError("Registry Error: Cannot register modules on a shutdown engine.")
            self._checks[name.strip()] = check_fn
            logger.info("Registry: Hook synchronized for module '%s'", name.strip())
        return self

    def unregister(self, name: str) -> bool:
        """Flushes a module from the active registry snapshot."""
        if not name or not isinstance(name, str):
            return False

        stripped_name = name.strip()
        with self._lock:
            if stripped_name in self._checks:
                del self._checks[stripped_name]
                logger.debug("Registry: Flushed module '%s'", stripped_name)
                return True
            return False

    def is_registered(self, name: str) -> bool:
        """Checks if a module check is currently registered."""
        if not name or not isinstance(name, str):
            return False
        with self._lock:
            return name.strip() in self._checks

    def get_registered_names(self) -> List[str]:
        """Returns a snapshot list of currently registered check module names."""
        with self._lock:
            return list(self._checks.keys())

    def _normalize(self, raw: Any) -> DiagnosticResult:
        """Transmutes diverse return types into high-integrity DiagnosticResult objects."""
        if isinstance(raw, DiagnosticResult):
            return raw
        if isinstance(raw, BaseException):
            return DiagnosticResult(
                passed=False,
                message=f"Check yielded exception: {type(raw).__name__}({str(raw)})",
                severity=DiagnosticSeverity.CRITICAL,
                metadata={"exception_type": type(raw).__name__, "exception_str": str(raw)}
            )
        if isinstance(raw, bool):
            return DiagnosticResult(
                passed=raw,
                message="Integrity verified" if raw else "Integrity breach detected",
                severity=DiagnosticSeverity.HIGH if not raw else DiagnosticSeverity.INFO
            )
        if isinstance(raw, (tuple, list)):
            if len(raw) >= 2:
                p = bool(raw[0])
                m = str(raw[1])
                s = DiagnosticSeverity.from_any(raw[2]) if len(raw) >= 3 else (DiagnosticSeverity.INFO if p else DiagnosticSeverity.HIGH)
                meta = dict(raw[3]) if len(raw) >= 4 and isinstance(raw[3], Mapping) else {}
                return DiagnosticResult(passed=p, message=m, severity=s, metadata=meta)
            elif len(raw) == 1:
                return self._normalize(raw[0])
        if isinstance(raw, Mapping):
            try:
                raw_severity = raw.get("severity", DiagnosticSeverity.MEDIUM)
                severity_val = DiagnosticSeverity.from_any(raw_severity, DiagnosticSeverity.MEDIUM)

                metadata_raw = raw.get("metadata", {})
                if isinstance(metadata_raw, dict):
                    metadata_dict = dict(metadata_raw)
                elif isinstance(metadata_raw, Mapping):
                    try:
                        metadata_dict = dict(metadata_raw)
                    except Exception:
                        metadata_dict = {"raw_metadata": str(metadata_raw)}
                else:
                    metadata_dict = {"raw_metadata": metadata_raw}

                return DiagnosticResult(
                    passed=bool(raw.get("passed", False)),
                    message=str(raw.get("message", "Telemetry captured")),
                    severity=severity_val,
                    metadata=metadata_dict
                )
            except Exception as norm_err:
                return DiagnosticResult(
                    passed=False,
                    message=f"Mapping normalization error: {norm_err}",
                    severity=DiagnosticSeverity.HIGH,
                    metadata={"raw": str(raw)}
                )
        if raw is None:
            return DiagnosticResult(
                passed=False,
                message="Diagnostic check returned None without status payload",
                severity=DiagnosticSeverity.MEDIUM
            )
        return DiagnosticResult(passed=bool(raw), message=str(raw))

    def _execute_isolated(self, name: str, check_fn: DiagnosticCheck) -> Dict[str, Any]:
        """
        Executes a diagnostic check within an isolated telemetry harness.
        Ensures exception containment, zero-leak state purging, and nanosecond duration tracking.
        """
        start_ns = time.perf_counter_ns()
        try:
            raw_output = check_fn()
            res = self._normalize(raw_output)
            duration_ms = round((time.perf_counter_ns() - start_ns) / 1_000_000.0, 4)
            timestamp = _safe_format_utc_timestamp()

            try:
                meta_payload = dict(res.metadata)
            except Exception:
                meta_payload = {"raw_metadata": str(res.metadata)}

            payload: Dict[str, Any] = {
                "passed": res.passed,
                "message": res.message,
                "severity": res.severity.name,
                "weight": res.severity.weight,
                "duration_ms": duration_ms,
                "metadata": meta_payload,
                "timestamp": timestamp
            }
            del raw_output, res
            return payload

        except Exception as e:
            duration_ms = round((time.perf_counter_ns() - start_ns) / 1_000_000.0, 4)
            logger.error("Diagnostic Fault [%s]: %s", name, e, exc_info=True)
            timestamp = _safe_format_utc_timestamp()
            return {
                "passed": False,
                "message": f"Critical Execution Failure: {type(e).__name__}({str(e)})",
                "severity": DiagnosticSeverity.CRITICAL.name,
                "weight": DiagnosticSeverity.CRITICAL.weight,
                "duration_ms": duration_ms,
                "metadata": {
                    "stack_trace": f"Exception raised: {type(e).__name__}",
                    "error_detail": str(e)
                },
                "timestamp": timestamp
            }

    def run_all(self, timeout: Optional[float] = None) -> Dict[str, Dict[str, Any]]:
        """
        Triggers a system-wide diagnostic sweep.
        Utilizes concurrent execution to prevent kernel blocking with non-leaking future harvesting.
        """
        with self._lock:
            if self._is_shutdown:
                raise RuntimeError("Engine Error: Diagnostics requested on shutdown instance.")
            tasks = list(self._checks.items())

        if not tasks:
            return {}

        if timeout is not None:
            try:
                exec_timeout = float(timeout)
                if exec_timeout != exec_timeout or exec_timeout <= 0.0:
                    exec_timeout = self._default_timeout
            except (ValueError, TypeError):
                exec_timeout = self._default_timeout
        else:
            exec_timeout = self._default_timeout

        results: Dict[str, Dict[str, Any]] = {}
        future_map: Dict[concurrent.futures.Future[Dict[str, Any]], str] = {}

        try:
            with self._lock:
                if self._is_shutdown:
                    raise RuntimeError("Engine Error: Executor was terminated during sweep scheduling.")
                for name, fn in tasks:
                    try:
                        future = self._executor.submit(self._execute_isolated, name, fn)
                        future_map[future] = name
                    except (RuntimeError, Exception) as re:
                        logger.error("Execution dispatch failed for module '%s': %s", name, re)
                        ts = _safe_format_utc_timestamp()
                        results[name] = {
                            "passed": False,
                            "message": f"Dispatch Failure: {str(re)}",
                            "severity": DiagnosticSeverity.CRITICAL.name,
                            "weight": DiagnosticSeverity.CRITICAL.weight,
                            "duration_ms": 0.0,
                            "metadata": {"dispatch_error": str(re)},
                            "timestamp": ts,
                        }

            if future_map:
                done, not_done = concurrent.futures.wait(
                    future_map.keys(),
                    timeout=exec_timeout,
                    return_when=concurrent.futures.ALL_COMPLETED,
                )

                for future in done:
                    name = future_map[future]
                    try:
                        res = future.result()
                        results[name] = res
                    except Exception as exc:
                        logger.error("Future extraction failure for module '%s': %s", name, exc)
                        ts = _safe_format_utc_timestamp()
                        results[name] = {
                            "passed": False,
                            "message": f"Future Execution Error: {type(exc).__name__}({str(exc)})",
                            "severity": DiagnosticSeverity.CRITICAL.name,
                            "weight": DiagnosticSeverity.CRITICAL.weight,
                            "duration_ms": round(exec_timeout * 1000.0, 4),
                            "metadata": {"error": str(exc)},
                            "timestamp": ts,
                        }

                for future in not_done:
                    name = future_map[future]
                    try:
                        future.cancel()
                    except Exception:
                        pass
                    logger.warning("Diagnostic check '%s' timed out after %s seconds", name, exec_timeout)
                    ts = _safe_format_utc_timestamp()
                    results[name] = {
                        "passed": False,
                        "message": f"Diagnostic Check Timed Out after {exec_timeout:.2f}s",
                        "severity": DiagnosticSeverity.HIGH.name,
                        "weight": DiagnosticSeverity.HIGH.weight,
                        "duration_ms": round(exec_timeout * 1000.0, 4),
                        "metadata": {"timeout_seconds": exec_timeout},
                        "timestamp": ts,
                    }
        finally:
            future_map.clear()

        return results

    def run_system_diagnostics(self, timeout: Optional[float] = None) -> Dict[str, Any]:
        """
        Executes all checks and compiles a full system diagnostic report including
        telemetry and calculated integrity summary.
        """
        raw_results = self.run_all(timeout=timeout)
        try:
            summary = calculate_summary(raw_results)
            if not isinstance(summary, dict):
                summary = {"raw_summary": summary}
        except Exception as err:
            logger.error("Failed to calculate diagnostic summary: %s", err)
            summary = {"error": f"Summary calculation failure: {err}"}

        try:
            telemetry = capture_system_telemetry()
            if not isinstance(telemetry, dict):
                telemetry = {"raw_telemetry": telemetry}
        except Exception as err:
            logger.error("Failed to capture system telemetry: %s", err)
            telemetry = {"error": f"Telemetry capture failure: {err}"}

        timestamp = _safe_format_utc_timestamp()

        return {
            "timestamp": timestamp,
            "summary": summary,
            "results": raw_results,
            "telemetry": telemetry,
        }

    def shutdown(self, wait: bool = True) -> None:
        """Gracefully shuts down the thread pool executor and disallows new submissions."""
        with self._lock:
            if self._is_shutdown:
                return
            self._is_shutdown = True
        try:
            atexit.unregister(self._cleanup_atexit)
        except Exception:
            pass
        try:
            self._executor.shutdown(wait=wait, cancel_futures=True)
        except TypeError:
            self._executor.shutdown(wait=wait)
        except Exception as err:
            logger.debug("Defensive shutdown exception suppressed: %s", err)


# Sovereign singleton instance
engine: DiagnosticEngine = DiagnosticEngine()


def register_check(
    name: Union[str, DiagnosticCheck], check_fn: Optional[DiagnosticCheck] = None
) -> Union[DiagnosticCheck, Callable[[DiagnosticCheck], DiagnosticCheck]]:
    """
    Module-level convenience registration hook.
    Supports direct registration, parameterized decorator, and bare decorator patterns:
        register_check("memory", check_memory)
        @register_check("memory")
        def check_memory(): ...
        @register_check
        def check_memory(): ...
    """
    if callable(name) and check_fn is None:
        fn = name
        module_name = getattr(fn, "__name__", str(fn))
        engine.register(module_name, fn)
        return fn

    if not isinstance(name, str) or not name.strip():
        raise ValueError("register_check requires a valid non-empty string identifier.")

    if check_fn is not None:
        engine.register(name, check_fn)
        return check_fn

    def decorator(fn: DiagnosticCheck) -> DiagnosticCheck:
        engine.register(name, fn)
        return fn

    return decorator


def run_system_diagnostics(timeout: Optional[float] = None) -> Dict[str, Any]:
    """
    Global convenience function executing a system-wide diagnostic sweep on the default engine.
    """
    return engine.run_system_diagnostics(timeout=timeout)

