def generate_registry_telemetry() -> Dict[str, Any]:
    """Generates standard telemetry metadata for registry diagnostic reports with microsecond time precision."""
    try:
        thread_id = threading.get_ident()
    except Exception:
        thread_id = 0

    try:
        node_hex = uuid.uuid4().hex[:8]
    except Exception:
        node_hex = "00000000"

