def compute_health_score(checks: Dict[str, RegistryDiagnosticResult]) -> float:
    """Computes a normalized health score (0.0 to 1.0) based on diagnostic results with zero-division safety."""
    if not isinstance(checks, (dict, Mapping)) or not checks:
        return 0.0
    try:
        total = len(checks)
        if total <= 0:
            return 0.0
        passed_count = 0
        for c in checks.values():
            try:
                if getattr(c, "passed", False) is True:
                    passed_count += 1
            except Exception:
                continue
        score = passed_count / float(total)
        return round(max(0.0, min(1.0, float(score))), 4)
    except (TypeError, AttributeError, ZeroDivisionError, ValueError):
        return 0.0


