@dataclass(frozen=True)
class DiagnosticResult:
    """
    An immutable, high-integrity record of a diagnostic check execution.
    Aligned with the Sovereign Evolution Engine v89.1 telemetry standards.
    """
    passed: bool
    message: str
    trace_id: str
    duration_ms: float
    integrity_score: float = 1.0
    metadata: Dict[str, Any] = field(default_factory=dict)
    version: str = DIAGNOSTIC_VERSION

    def __post_init__(self) -> None:
        """Enforces defensive invariants on immutable diagnostic data."""
        # Sanitize boolean passed status
        object.__setattr__(self, "passed", bool(self.passed))

        # Sanitize textual fields against None or non-string inputs
        object.__setattr__(self, "message", str(self.message) if self.message is not None else "")
        object.__setattr__(self, "trace_id", str(self.trace_id) if self.trace_id is not None else "")
        object.__setattr__(self, "version", str(self.version) if self.version is not None else DIAGNOSTIC_VERSION)

        # Sanitize integrity score safely within [0.0, 1.0]
        raw_score = self.integrity_score
        sanitized_score = 1.0 if self.passed else 0.0
        try:
            val = float(raw_score)
            if not (math.isnan(val) or math.isinf(val)):
                sanitized_score = max(0.0, min(1.0, val))
        except (TypeError, ValueError):
            pass
        object.__setattr__(self, "integrity_score", sanitized_score)

        # Sanitize duration_ms to non-negative float
        sanitized_duration = 0.0
        try:
            dur = float(self.duration_ms)
            if not (math.isnan(dur) or math.isinf(dur)):
                sanitized_duration = max(0.0, dur)
        except (TypeError, ValueError):
            pass
        object.__setattr__(self, "duration_ms", sanitized_duration)

        # Defensively isolate metadata dictionary to prevent external mutation
        raw_meta = self.metadata
        if isinstance(raw_meta, dict):
            try:
                object.__setattr__(self, "metadata", dict(raw_meta))
            except Exception:
                object.__setattr__(self, "metadata", {"error": "Metadata shallow copy failure"})
        else:
            object.__setattr__(self, "metadata", {"raw_metadata": repr(raw_meta)})

    def to_dict(self) -> Dict[str, Any]:
        """Serializes the diagnostic result into a standardized dictionary."""
        try:
            meta_copy = dict(self.metadata)
        except Exception:
            meta_copy = {"raw_metadata": repr(self.metadata)}

        return {
            "passed": bool(self.passed),
            "message": str(self.message),
            "trace_id": str(self.trace_id),
            "duration_ms": float(self.duration_ms),
            "integrity_score": float(self.integrity_score),
            "metadata": meta_copy,
            "version": str(self.version),
        }


@dataclass
class DiagnosticContext:
    """Execution context for stateful diagnostic routines."""
    correlation_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    start_time: float = field(default_factory=time.perf_counter)
    caller_identity: Optional[str] = None
    attributes: Dict[str, Any] = field(default_factory=dict)
    _lock: threading.RLock = field(default_factory=threading.RLock, init=False, repr=False, compare=False)

    def __post_init__(self) -> None:
        """Guarantees structural validity of initialization fields."""
        if not hasattr(self, "_lock") or self._lock is None:
            self._lock = threading.RLock()

        self.correlation_id = str(self.correlation_id) if self.correlation_id is not None else str(uuid.uuid4())
        try:
            st = float(self.start_time)
            self.start_time = st if not (math.isnan(st) or math.isinf(st)) else time.perf_counter()
        except (TypeError, ValueError):
            self.start_time = time.perf_counter()

        if isinstance(self.attributes, dict):
            self.attributes = dict(self.attributes)
        else:
            try:
                self.attributes = dict(self.attributes)
            except Exception:
                self.attributes = {}

    def elapsed_ms(self) -> float:
        """Calculates execution elapsed time in milliseconds since context instantiation."""
        return max(0.0, (time.perf_counter() - self.start_time) * 1000.0)

    def set_attribute(self, key: str, value: Any) -> None:
        """Thread-safe setter for context attributes."""
        with self._lock:
            self.attributes[str(key)] = value

    def get_attribute(self, key: str, default: Any = None) -> Any:
        """Thread-safe getter for context attributes."""
        with self._lock:
            return self.attributes.get(str(key), default)

    def get_all_attributes(self) -> Dict[str, Any]:
        """Thread-safe snapshot getter for all context attributes."""
        with self._lock:
            return dict(self.attributes)

    def create_child(self, caller_identity: Optional[str] = None) -> DiagnosticContext:
        """Derives a synchronized child context preserving the correlation lineage."""
        with self._lock:
            cloned_attrs = dict(self.attributes)
        return DiagnosticContext(
            correlation_id=self.correlation_id,
            start_time=time.perf_counter(),
            caller_identity=caller_identity or self.caller_identity,
            attributes=cloned_attrs,
        )

    def __enter__(self) -> DiagnosticContext:
        """Context management entry."""
        return self

    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        """Context management exit handler."""
        pass


def validate_diagnostic_signature(func: Callable[..., Any]) -> bool:
    """
    Performs deep inspection of a diagnostic check function to ensure compatibility
    with the Kernel's execution harness.

    Checks for:
    1. Callability.
    2. Acceptance of keyword arguments (kwargs) or targeted telemetry injection parameters.
    """
    if not callable(func):
        return False

    try:
        target = inspect.unwrap(func)
        sig = inspect.signature(target)
        has_var_kwargs = any(p.kind == inspect.Parameter.VAR_KEYWORD for p in sig.parameters.values())
        has_context_param = "context" in sig.parameters
        has_trace_id_param = "trace_id" in sig.parameters
        return bool(has_var_kwargs or has_context_param or has_trace_id_param)
    except (ValueError, TypeError, RecursionError, AttributeError):
        # Functions like C-extensions, built-ins, recursion loops, or proxy types without signature introspection
        return False
    except Exception:
        return False


def capture_diagnostic_execution(
    check_func: Callable[..., Any], 
    *args: Any, 
    **kwargs: Any
) -> DiagnosticResult:
    """
    A high-order execution harness that wraps diagnostic logic in a telemetry 
    envelope. Handles timing, exception isolation, parameter introspection, 
    and trace ID generation.

    Args:
        check_func: The diagnostic function to execute.
        *args: Positional arguments for the check.
        **kwargs: Keyword arguments for the check.

    Returns:
        DiagnosticResult: The finalized diagnostic record.
    """
    trace_id = str(uuid.uuid4())
    start_ts = time.perf_counter()
    thread_id = threading.get_ident()
    extra_meta: Dict[str, Any] = {}

    try:
        timestamp_ns = time.time_ns()
    except (AttributeError, Exception):
        timestamp_ns = int(time.time() * 1_000_000_000)

    if not callable(check_func):
        end_ts = time.perf_counter()
        return DiagnosticResult(
            passed=False,
            message="Diagnostic Critical Failure: Provided check_func is not callable",
            trace_id=trace_id,
            duration_ms=round(max(0.0, (end_ts - start_ts) * 1000.0), 4),
            integrity_score=0.0,
            metadata={
                "thread_id": thread_id,
                "engine_mode": "EVOLUTION_V89.1",
                "timestamp_ns": timestamp_ns,
                "invalid_target": repr(check_func),
            },
            version=DIAGNOSTIC_VERSION,
        )

    # Defensively copy incoming kwargs to avoid caller state contamination
    call_kwargs = dict(kwargs)

    try:
        # Introspect target signature to safely inject telemetry context without collision
        try:
            target = inspect.unwrap(check_func)
            sig = inspect.signature(target)
            has_var_kwargs = any(p.kind == inspect.Parameter.VAR_KEYWORD for p in sig.parameters.values())

            # Only inject if parameter can be received as a keyword argument
            trace_id_param = sig.parameters.get("trace_id")
            can_inject_trace_id = has_var_kwargs or (
                trace_id_param is not None and trace_id_param.kind != inspect.Parameter.POSITIONAL_ONLY
            )
            if can_inject_trace_id:
                call_kwargs.setdefault("trace_id", trace_id)

            context_param = sig.parameters.get("context")
            can_inject_context = (
                context_param is not None and context_param.kind != inspect.Parameter.POSITIONAL_ONLY
            )
            if (can_inject_context or has_var_kwargs) and "context" not in call_kwargs:
                if can_inject_context:
                    call_kwargs["context"] = DiagnosticContext(
                        correlation_id=trace_id, 
                        start_time=start_ts
                    )
        except (ValueError, TypeError, RecursionError, AttributeError):
            # Builtins, C-extensions, or custom wrappers that reject signature inspection
            pass
        except Exception:
            # Fallback for dynamic proxy unwrapping issues
            pass

        result_payload = check_func(*args, **call_kwargs)

        # Normalize various return signatures safely
        if isinstance(result_payload, DiagnosticResult):
            return result_payload
        elif isinstance(result_payload, tuple) and len(result_payload) >= 2:
            passed = bool(result_payload[0])
            message = str(result_payload[1])
            if len(result_payload) > 2 and isinstance(result_payload[2], dict):
                extra_meta = dict(result_payload[2])
            elif len(result_payload) > 2:
                extra_meta = {"payload": result_payload[2]}
        else:
            passed = bool(result_payload)
            message = "Execution completed" if passed else "Check returned false or empty payload"
            extra_meta = {}

    except Exception as e:
        passed = False
        message = f"Diagnostic Critical Failure: {type(e).__name__} -> {str(e)}"
        try:
            formatted_tb = traceback.format_exc()
        except Exception:
            formatted_tb = "Traceback extraction failed"
        extra_meta = {
            "exception_type": type(e).__name__,
            "exception_message": str(e),
            "traceback": formatted_tb,
        }

    end_ts = time.perf_counter()
    duration_ms = max(0.0, (end_ts - start_ts) * 1000.0)

    raw_integrity = extra_meta.pop("integrity_score", 1.0 if passed else 0.0)
    try:
        integrity_score = float(raw_integrity)
        if math.isnan(integrity_score) or math.isinf(integrity_score):
            integrity_score = 1.0 if passed else 0.0
        else:
            integrity_score = max(0.0, min(1.0, integrity_score))
    except (TypeError, ValueError):
        integrity_score = 1.0 if passed else 0.0

    final_metadata = {
        **extra_meta,
        "thread_id": thread_id,
        "engine_mode": "EVOLUTION_V89.1",
        "timestamp_ns": timestamp_ns,
    }

    return DiagnosticResult(
        passed=passed,
        message=message,
        trace_id=trace_id,
        duration_ms=round(duration_ms, 4),
        integrity_score=integrity_score,
        metadata=final_metadata,
        version=DIAGNOSTIC_VERSION,
    )

