@dataclass(frozen=True, slots=True)
class TelemetryStatsResult:
    """Structured container for statistical analysis results."""
    mean: float
    variance: float
    std_dev: float
    min: float
    max: float
    count: int

    def to_dict(self) -> Dict[str, Any]:
        """Converts statistical analysis result into a primitive dictionary representation."""
        return {
            "mean": float(self.mean) if math.isfinite(self.mean) else 0.0,
            "variance": float(self.variance) if math.isfinite(self.variance) and self.variance >= 0.0 else 0.0,
            "std_dev": float(self.std_dev) if math.isfinite(self.std_dev) and self.std_dev >= 0.0 else 0.0,
            "min": float(self.min) if math.isfinite(self.min) else 0.0,
