# Constants for Integrity Weighting & Security
INTEGRITY_THRESHOLD: Final[float] = 0.95
DEFAULT_PRECISION: Final[int] = 4
MAX_RECURSION_DEPTH: Final[int] = 32

SENSITIVE_PATTERN_REGEX: Final[re.Pattern[str]] = re.compile(
    r"(?i)\b(key|token|secret|password|auth|bearer|api[_-]?key|private[_-]?key)\b\s*[:=]\s*[^\s,;]+",
    re.IGNORECASE,
)

BEARER_AUTH_REGEX: Final[re.Pattern[str]] = re.compile(
    r"(?i)\b(bearer)\s+[A-Za-z0-9_\-\.]+",
    re.IGNORECASE,
)


class TelemetryPayload(TypedDict):
    """Encapsulates execution metadata for a single diagnostic unit."""

    check_id: str
