def format_timestamp() -> str:
    """Returns high-precision ISO 8601 formatted UTC timestamp with Z suffix.

    Optimized for kernel-level event ordering and log ingestion.
    """
    try:
        return (
            datetime.now(timezone.utc)
            .isoformat(timespec="microseconds")
            .replace("+00:00", "Z")
        )
    except Exception:
        # Fallback to standard time module in edge-case clock/runtime anomalies
        return time.strftime("%Y-%m-%dT%H:%M:%S.000000Z", time.gmtime())


def scrub_context(text: str) -> str:
    """Zero-Leak implementation: Redacts potentially sensitive data from error

    contexts or logs using compiled regex.
    """
    if not text:
        return ""
    if not isinstance(text, str):
        try:
            text = str(text)
        except Exception:
            return "[UNPARSEABLE_CONTEXT]"

    try:
        redacted = SENSITIVE_PATTERN_REGEX.sub(r"\1=REDACTED", text)
        return BEARER_AUTH_REGEX.sub(r"\1 REDACTED", redacted)
    except Exception:
        return "[SANITIZATION_FAILED]"


def _scrub_nested_metadata(
    item: Any,
    seen: set[int] | None = None,
    depth: int = 0,
    max_depth: int = MAX_RECURSION_DEPTH,
) -> Any:
    """Recursively traverses and sanitizes nested diagnostic metadata

    to preserve Zero-Leak constraints across complex data structures.
    Defensively guards against circular references and maximum recursion limits.
    """
    if depth > max_depth:
        return "[MAX_DEPTH_EXCEEDED]"

    if seen is None:
        seen = set()

    is_container = isinstance(item, (dict, list, tuple, set))
    item_id = None
    if is_container:
        item_id = id(item)
        if item_id in seen:
            return "[CIRCULAR_REFERENCE]"
        seen.add(item_id)

    try:
        if isinstance(item, str):
            return scrub_context(item)

        if isinstance(item, dict):
            sanitized_dict: dict[str, Any] = {}
            for key, value in item.items():
                safe_key = scrub_context(str(key))
                sanitized_dict[safe_key] = _scrub_nested_metadata(
                    value, seen=seen, depth=depth + 1, max_depth=max_depth
                )
            return sanitized_dict

        if isinstance(item, (list, tuple, set)):
            sanitized_seq = [
                _scrub_nested_metadata(elem, seen=seen, depth=depth + 1, max_depth=max_depth)
                for elem in item
            ]
            return type(item)(sanitized_seq) if isinstance(item, (list, tuple)) else sanitized_seq

        return item
    except Exception as exc:
        return f"[SCRUB_ERROR: {scrub_context(type(exc).__name__)}]"
    finally:
        if is_container and item_id is not None and item_id in seen:
            seen.discard(item_id)


def _extract_and_scrub_metadata(result: Any) -> dict[str, Any]:
    """Safely extracts and sanitizes metadata from execution results."""
    try:
        if isinstance(result, dict):
            if "metadata" in result and isinstance(result["metadata"], dict):
                scrubbed = _scrub_nested_metadata(result["metadata"])
                return scrubbed if isinstance(scrubbed, dict) else {"metadata": scrubbed}
            scrubbed = _scrub_nested_metadata(result)
            return scrubbed if isinstance(scrubbed, dict) else {"raw_result": scrubbed}

        if result is not None:
            return {"raw_result": _scrub_nested_metadata(result)}

        return {}
    except Exception as scrub_err:
        return {"scrub_error": scrub_context(str(scrub_err))}


def calculate_integrity_score(passed: int, total: int) -> float:
    """Calculates the Diagnostic Integrity Score for Consensus Weighting.

    Implements a non-linear exponential decay for failures to penalize system
    instability. Formula: (passed/total)^2 * 0.95 if failures exist.
    """
    if isinstance(passed, bool) or isinstance(total, bool):
        return 0.0

    if not isinstance(passed, int) or not isinstance(total, int):
        try:
            passed = int(passed)
            total = int(total)
        except (ValueError, TypeError):
            return 0.0

    if total <= 0:
        return 0.0

    sanitized_passed = max(0, min(passed, total))
    ratio = sanitized_passed / float(total)

    if ratio >= 1.0:
        return 1.0

    score = (ratio**2) * INTEGRITY_THRESHOLD
    return round(max(0.0, score), DEFAULT_PRECISION)


def calculate_consensus_weight(integrity_score: float, base_weight: float = 1.0) -> float:
    """Computes dynamic consensus weight based on agent integrity score.

    Applies threshold gating: agents below INTEGRITY_THRESHOLD suffer scaled
    voting weight degradation.
    """
    if isinstance(integrity_score, bool) or isinstance(base_weight, bool):
        return 0.0

    try:
        score = float(integrity_score)
        weight = float(base_weight)
    except (ValueError, TypeError):
        return 0.0

    if math.isnan(score) or math.isinf(score) or score <= 0.0:
        return 0.0
    if math.isnan(weight) or math.isinf(weight) or weight <= 0.0:
        return 0.0

    clamped_score = min(score, 1.0)

    if clamped_score < INTEGRITY_THRESHOLD:
        degradation = (clamped_score / INTEGRITY_THRESHOLD) ** 2
        return round(max(0.0, weight * degradation), DEFAULT_PRECISION)

    return round(max(0.0, weight * clamped_score), DEFAULT_PRECISION)


def execute_check_with_telemetry(
    component: str,
    check_func: Callable[P, Any],
    *args: P.args,
    **kwargs: P.kwargs,
) -> TelemetryPayload:
    """Executes a diagnostic check wrapped in a telemetry harness.

    Captures duration via high-resolution nanosecond timer, outcome, and scrubs
    error contexts for Zero-Leak compliance.
    """
    check_id = str(uuid.uuid4())
    component_name = str(component) if component is not None else "unknown_component"
    start_ns = time.perf_counter_ns()

    status = False
    error_context: str | None = None
    metadata: dict[str, Any] = {}

    try:
        if not callable(check_func):
            raise TypeError(f"Target check_func is not callable: {type(check_func).__name__}")

        result = check_func(*args, **kwargs)
        status = True
        metadata = _extract_and_scrub_metadata(result)

    except Exception as exc:
        status = False
        raw_error = f"{type(exc).__name__}: {exc}\n{traceback.format_exc()}"
        error_context = scrub_context(raw_error)
    finally:
        elapsed_ns = max(0, time.perf_counter_ns() - start_ns)
        elapsed_ms = elapsed_ns / 1_000_000.0

    return {
        "check_id": check_id,
        "component": component_name,
        "status": status,
        "duration_ms": round(max(0.0, elapsed_ms), DEFAULT_PRECISION),
        "error_context": error_context,
        "timestamp": format_timestamp(),
        "metadata": metadata,
    }


def telemetry_harness(component: str) -> Callable[[Callable[P, R]], Callable[P, TelemetryPayload]]:
    """Decorator variant of execute_check_with_telemetry to wrap functions seamlessly."""

    def decorator(func: Callable[P, R]) -> Callable[P, TelemetryPayload]:
        @functools.wraps(func)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> TelemetryPayload:
            return execute_check_with_telemetry(component, func, *args, **kwargs)

        return wrapper

    return decorator


def summarize_diagnostic_results(
    results: Sequence[TelemetryPayload],
    session_id: str | None = None,
) -> DiagnosticSummary:
    """Synthesizes an aggregated diagnostic snapshot across telemetry payloads.

    Calculates holistic integrity score, health predicates, latency metrics,
    and isolates failing components for defensive isolation.
    """
    effective_session_id = (
        str(session_id).strip() if session_id and str(session_id).strip() else str(uuid.uuid4())
    )
    current_ts = format_timestamp()

    try:
        results_list = list(results) if results is not None else []
    except Exception:
        results_list = []

    total = len(results_list)
    if total == 0:
        return {
            "session_id": effective_session_id,
            "timestamp": current_ts,
            "total_checks": 0,
            "passed": 0,
            "failed": 0,
            "is_healthy": False,
            "integrity_score": 0.0,
            "critical_failures": [],
            "latency_avg_ms": 0.0,
        }

    passed = 0
    critical_failures: list[str] = []
    total_duration_ms = 0.0

    for check in results_list:
        if not isinstance(check, dict):
            critical_failures.append("malformed_check_payload")
            continue

        is_passed = bool(check.get("status", False))
        comp_name = str(check.get("component", "unknown_component"))
        duration = check.get("duration_ms", 0.0)

        if isinstance(duration, (int, float)) and not math.isnan(duration) and not math.isinf(duration):
            total_duration_ms += max(0.0, float(duration))

        if is_passed:
            passed += 1
        else:
            critical_failures.append(comp_name)

    failed = total - passed
    integrity = calculate_integrity_score(passed, total)
    is_healthy = (failed == 0) and (integrity >= INTEGRITY_THRESHOLD)
    latency_avg = round(total_duration_ms / total, DEFAULT_PRECISION) if total > 0 else 0.0

    return {
        "session_id": effective_session_id,
        "timestamp": current_ts,
        "total_checks": total,
        "passed": passed,
        "failed": failed,
        "is_healthy": is_healthy,
        "integrity_score": integrity,
        "critical_failures": critical_failures,
        "latency_avg_ms": latency_avg,
    }

