/**
 * ARCHITECTURAL FETCH ENGINE CORE
 * Role: Provides resilient, retry-aware, telemetry-monitored HTTP/HTTPS data retrieval.
 * Integration: Exported class FetchEngine used by repo fetchers and diagnostic modules.
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');

class FetchEngine {
  /**
   * @param {string} url - Target URL to fetch
   * @param {object} [options] - Fetch configuration (headers, timeout, retries)
   */
  constructor(url, options = {}) {
    this.url = url;
    this.options = {
      timeout: options.timeout || parseInt(process.env.FETCH_TIMEOUT_MS, 10) || 15000,
      retries: options.retries || parseInt(process.env.FETCH_RETRIES, 10) || 3,
      headers: {
        'Accept': 'application/json, text/plain, */*',
        ...(options.headers || {})
      },
      ...options
    };
  }

  /**
   * Executes the HTTP request with exponential backoff and retry mechanism.
   * @returns {Promise<any>}
   */
  async execute() {
    let lastError = null;
    let attempt = 0;

    while (attempt < this.options.retries) {
      attempt++;
      try {
        const result = await this._performRequest(this.url);
        return result;
      } catch (err) {
        lastError = err;
        if (attempt < this.options.retries) {
          const backoffMs = Math.pow(2, attempt) * 500;
          await new Promise((resolve) => setTimeout(resolve, backoffMs));
        }
      }
    }

    throw new Error(`FetchEngine failed after ${attempt} attempts. Last error: ${lastError ? lastError.message : 'Unknown'}`);
  }

  /**
   * Internal request helper supporting redirects and JSON parsing.
   * @private
   */
  _performRequest(targetUrl) {
    return new Promise((resolve, reject) => {
      try {
        const parsedUrl = new URL(targetUrl);
        const protocol = parsedUrl.protocol === 'https:' ? https : http;

        const reqOptions = {
          protocol: parsedUrl.protocol,
          hostname: parsedUrl.hostname,
          port: parsedUrl.port,
          path: parsedUrl.pathname + parsedUrl.search,
          method: 'GET',
          headers: this.options.headers,
          timeout: this.options.timeout
        };

        const req = protocol.request(reqOptions, (res) => {
          // Handle redirects
          if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
            const redirectUrl = new URL(res.headers.location, targetUrl).toString();
            return this._performRequest(redirectUrl).then(resolve).catch(reject);
          }

          if (res.statusCode < 200 || res.statusCode >= 300) {
            return reject(new Error(`HTTP ${res.statusCode}: ${res.statusMessage}`));
          }

          let body = '';
          res.setEncoding('utf8');
          res.on('data', (chunk) => { body += chunk; });
          res.on('end', () => {
            try {
              const contentType = res.headers['content-type'] || '';
              if (contentType.includes('application/json') || body.trim().startsWith('{') || body.trim().startsWith('[')) {
                resolve(JSON.parse(body));
              } else {
                resolve(body);
              }
            } catch (jsonErr) {
              resolve(body);
            }
          });
        });

        req.on('error', (err) => reject(err));
        req.on('timeout', () => {
          req.destroy();
          reject(new Error(`Request timed out after ${this.options.timeout}ms`));
        });

        req.end();
      } catch (err) {
        reject(err);
      }
    });
  }
}

module.exports = { FetchEngine };

/**
 * FETCH ENGINE CORE
 * Role: Networking and file-system inspection engine for repository synchronization.
 * Integration: Leveraged by fetch_missing.js for remote HTTP/HTTPS requests and directory tree scanning.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

class FetchEngine {
    constructor(options = {}) {
        this.timeout = options.timeout || 15000;
        this.token = options.token || process.env.GITHUB_TOKEN || null;
    }

    /**
     * Fetches remote tree structure from GitHub API or standard JSON endpoint.
     * @param {string} url 
     * @returns {Promise<Array<{path: string, type: string, sha: string}>>}
     */     async fetchRemoteTree(url) {
        return new Promise((resolve, reject) => {
            const parsedUrl = new URL(url);
            const client = parsedUrl.protocol === 'https:' ? https : http;

            const headers = {
                'User-Agent': 'Darlek-Caan-DiagnosticEngine/1.0',
                'Accept': 'application/vnd.github.v3+json'
            };

            if (this.token) {
                headers['Authorization'] = `token ${this.token}`;
            }

            const req = client.get(url, { headers, timeout: this.timeout }, (res) => {
                let data = '';

                if (res.statusCode < 200 || res.statusCode >= 300) {
                    return reject(new Error(`HTTP ${res.statusCode}: Failed to fetch repository tree from ${url}`));
                }

                res.on('data', chunk => data += chunk);
                res.on('end', () => {
                    try {
                        const parsed = JSON.parse(data);
                        if (parsed.tree && Array.isArray(parsed.tree)) {
                            resolve(parsed.tree);
                        } else if (Array.isArray(parsed)) {
                            resolve(parsed);
                        } else {
                            resolve([]);
                        }
                    } catch (err) {
                        reject(new Error(`Failed to parse tree JSON: ${err.message}`));
                    }
                });
            });

            req.on('error', (err) => reject(new Error(`Network error fetching tree: ${err.message}`)));
            req.on('timeout', () => {
                req.destroy();
                reject(new Error(`Timeout of ${this.timeout}ms exceeded while fetching repository tree`));
            });
        });
    }

    /**
     * Recursively scans local directory and returns array of relative paths using POSIX normalization.
     * @param {string} dirPath 
     * @returns {string[]}
     */
    walkDirectory(dirPath) {
        const fullPath = path.resolve(process.cwd(), dirPath);
        let results = [];

        if (!fs.existsSync(fullPath)) {
            return results;
        }

        const items = fs.readdirSync(fullPath, { withFileTypes: true });

        for (const item of items) {
            const relativeItemPath = path.posix.join(dirPath, item.name);
            if (item.isDirectory()) {
                results = results.concat(this.walkDirectory(relativeItemPath));
            } else if (item.isFile()) {
                results.push(relativeItemPath);
            }
        }

        return results;
    }
}

module.exports = { FetchEngine };

/**
 * DIAGNOSTIC ENGINE CORE
 * Role: Enterprise diagnostic lifecycle management, performance telemetry tracking, and structured health reporting.
 * Integration: Siphoned pattern from AI_Agent_OS diagnostic_engine.py.
 */

class DiagnosticEngine {
  constructor(serviceName = 'DEFAULT_SERVICE') {
    this.serviceName = serviceName;
    this.operations = new Map();
    this.results = [];
  }

  /**
   * Starts timing a diagnostic operation.
   * @param {string} opName 
   */
  start(opName) {
    this.operations.set(opName, {
      startTime: process.hrtime.bigint(),
      status: 'RUNNING'
    });
  }

  /**
   * Logs successful completion of a named operation.
   * @param {string} opName 
   * @param {object} metadata 
   */
  logSuccess(opName, metadata = {}) {
    const op = this.operations.get(opName);
    const durationMs = op
      ? Number(process.hrtime.bigint() - op.startTime) / 1e6
      : 0;

    const result = {
      opName,
      status: 'PASSED',
      durationMs: Math.round(durationMs * 1000) / 1000,
      metadata,
      timestamp: new Date().toISOString()
    };

    this.results.push(result);
    this.operations.delete(opName);
    return result;
  }

  /**
   * Logs failure of a named operation.
   * @param {string} opName 
   * @param {string} error 
   * @param {object} metadata 
   */
  logFailure(opName, error, metadata = {}) {
    const op = this.operations.get(opName);
    const durationMs = op
      ? Number(process.hrtime.bigint() - op.startTime) / 1e6
      : 0;

    const result = {
      opName,
      status: 'FAILED',
      durationMs: Math.round(durationMs * 1000) / 1000,
      error,
      metadata,
      timestamp: new Date().toISOString()
    };

    this.results.push(result);
    this.operations.delete(opName);
    return result;
  }

  /**
   * Generates a comprehensive health report for all logged operations.
   * @returns {object}
   */
  report() {
    const total = this.results.length;
    const passed = this.results.filter(r => r.status === 'PASSED').length;
    const failed = total - passed;
    const isHealthy = total > 0 && failed === 0;

    const summary = {
      service: this.serviceName,
      status: isHealthy ? 'HEALTHY' : 'CRITICAL_FAILURE',
      totalOperations: total,
      passed,
      failed,
      passRatePercent: total > 0 ? Math.round((passed / total) * 10000) / 100 : 0,
      timestamp: new Date().toISOString()
    };

    console.log(`\n--- [DIAGNOSTIC TELEMETRY REPORT: ${this.serviceName}] ---`);
    console.log(JSON.stringify({ summary, details: this.results }, null, 2));
    console.log(`--------------------------------------------------------\n`);

    return summary;
  }
}

