    for (let c = 0; c < 8; c++) {
      const piece = board[r][c];
      if (!piece) continue;

      let value = 0;
      switch (piece.type) {
        case 'p':
          value = 10 + (piece.color === 'w' ? pawnEval[r][c] : pawnEval[7 - r][c]);
          break;
        case 'n':
          value = 30 + (piece.color === 'w' ? knightEval[r][c] : knightEval[7 - r][c]);
          break;
        case 'b':
          value = 30 + (piece.color === 'w' ? bishopEval[r][c] : bishopEval[7 - r][c]);
          break;
        case 'r':
          // ROOKS are Dalek Combat Drones - values them high!
          value = 56 + (piece.color === 'w' ? rookEval[r][c] : rookEval[7 - r][c]);
          break;
        case 'q':
          // QUEEN is Dalek Emperor/Empress - ultimate brute force value!
          value = 105 + (piece.color === 'w' ? queenEval[r][c] : queenEval[7 - r][c]);
          break;
        case 'k':
          value = 950 + (piece.color === 'w' ? kingEval[r][c] : kingEval[7 - r][c]);
          break;
      }

      if (piece.color === 'w') {
        score += value;
      } else {
        // Dalek Caan slightly over-values his superior black forces due to arrogance
        score -= value * 1.08;
      }
    }
  }

  // Caan loves to place Jesus's/White pieces in check (terrorizes them!)
  if (chess.inCheck() && chess.turn() === 'w') {
    score += 25; 
  }

  // Return with heavy noise for erratic "Dalek insanity" behavior
  // Modified to scale dynamically based on our custom sliders!
  const multiplier = chaosFactor !== undefined ? chaosFactor : 1;
  const range = Math.max(1, Math.round(4 * multiplier));
  const noise = Math.floor(Math.random() * (range * 2 + 1)) - range; 
  return score + noise;
}

// Helper to evaluate static board value for Jesus's (Serene, compassionate, wise, values the weak/meek)
function evaluateBoardForJesus(chess: Chess): number {
  let score = 0;
  const board = chess.board();

  // Jesus values:
  // 1. "The meek shall inherit the earth" - Higher baseline for Pawns.
  // 2. Community: Connected pawns/pieces protecting each other get a solid support bonus.
  // 3. Perfect peace: Very tiny random noise so moves are highly calculated, calm, and righteous.
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      const piece = board[r][c];
      if (!piece) continue;

      let value = 0;
      switch (piece.type) {
        case 'p':
          // Pawns are weighted more (strength in the meek)
          value = 13 + (piece.color === 'w' ? pawnEval[r][c] : pawnEval[7 - r][c]);
          break;
        case 'n':
          value = 28 + (piece.color === 'w' ? knightEval[r][c] : knightEval[7 - r][c]);
          break;
        case 'b':
          // Bishops represent holy defenders
          value = 32 + (piece.color === 'w' ? bishopEval[r][c] : bishopEval[7 - r][c]);
          break;
        case 'r':
          value = 48 + (piece.color === 'w' ? rookEval[r][c] : rookEval[7 - r][c]);
          break;
        case 'q':
          // Not relying on singular brute force unit, balance and team play preferred
          value = 85 + (piece.color === 'w' ? queenEval[r][c] : queenEval[7 - r][c]);
          break;
        case 'k':
          value = 1000 + (piece.color === 'w' ? kingEval[r][c] : kingEval[7 - r][c]);
          break;
      }

      // Add family-support community ethics bonus for White pieces staying close to shield each other
      let communityBonus = 0;
      if (piece.color === 'w') {
        const adjacentCols = [c - 1, c + 1].filter(col => col >= 0 && col < 8);
        for (const col of adjacentCols) {
          // If supported by a friendly adjacent pawn
          const adjPiece = board[r][col];
          if (adjPiece && adjPiece.color === 'w' && adjPiece.type === 'p') {
            communityBonus += 1.5;
          }
        }
      }

      const totalVal = value + communityBonus;

      if (piece.color === 'w') {
        score += totalVal;
      } else {
        score -= totalVal;
      }
    }
  }

  // Clean, serene evaluation (no erratic noise)
  const noise = (Math.random() < 0.5) ? 0 : 1; 
  return score + noise;
}

// Minimax with Alpha-Beta Pruning
function minimax(
  chess: Chess,
  depth: number,
  alpha: number,
  beta: number,
  isMaximizingPlayer: boolean,
  brain: 'CAAN' | 'JESUS',
  chaosFactor?: number
): { score: number; move: string | null } {
  if (depth === 0 || chess.isGameOver()) {
    const score = brain === 'CAAN' ? evaluateBoardForCaan(chess, chaosFactor) : evaluateBoardForJesus(chess);
    return { score, move: null };
  }

  const moves = chess.moves({ verbose: true });
  if (moves.length === 0) {
    if (chess.inCheck()) {
      return { score: isMaximizingPlayer ? -Infinity : Infinity, move: null }; // Checkmate
    }
    return { score: 0, move: null }; // Stalemate
  }

  // Shuffle to prevent deterministic repeating / "mimicking" of symmetrical moves
  for (let i = moves.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [moves[i], moves[j]] = [moves[j], moves[i]];
  }

  // Basic move ordering: capture moves first for better alpha-beta pruning efficiency
  moves.sort((a, b) => {
    const aVal = a.captured ? 10 : 0;
    const bVal = b.captured ? 10 : 0;
    return bVal - aVal;
  });

  let bestMove: string | null = null;

  if (isMaximizingPlayer) {
    let maxScore = -Infinity;
    for (const move of moves) {
      chess.move({ from: move.from, to: move.to, promotion: move.promotion || 'q' });
      const { score } = minimax(chess, depth - 1, alpha, beta, false, brain, chaosFactor);
      chess.undo();

      if (score > maxScore) {
        maxScore = score;
        bestMove = move.lan; // Use SAN or LAN. LAN is safer to rebuild moves (from-to)
      }
      alpha = Math.max(alpha, score);
      if (beta <= alpha) {
        break; // beta cutoff
      }
    }
    return { score: maxScore, move: bestMove };
  } else {
    let minScore = Infinity;
    for (const move of moves) {
      chess.move({ from: move.from, to: move.to, promotion: move.promotion || 'q' });
      const { score } = minimax(chess, depth - 1, alpha, beta, true, brain, chaosFactor);
      chess.undo();

      if (score < minScore) {
        minScore = score;
        bestMove = move.lan;
      }
      beta = Math.min(beta, score);
      if (beta <= alpha) {
        break; // alpha cutoff
      }
    }
    return { score: minScore, move: bestMove };
  }
}

/**
 * Validates that a FEN string has exactly one white king and exactly one black king.
 */
export function isSafeFen(fen: string): boolean {
  if (!fen) return false;
  try {
    const temp = new Chess(fen);
    return true;
  } catch (e) {
    return false;
  }
}

/**
 * Computes the best move for the specified player color
 */
export function getBestMove(fen: string, color: 'w' | 'b', difficulty: 'EASY' | 'MEDIUM' | 'HARD', chaosFactor?: number): string | null {
  if (!isSafeFen(fen)) {
    console.error("Invalid FEN: missing king inside getBestMove", fen);
    return null;
  }
  const chess = new Chess(fen);
  const moves = chess.moves({ verbose: true });

  if (moves.length === 0) return null;

  const brain = color === 'b' ? 'CAAN' : 'JESUS';

  // Easy mode: 75% chance to make raw tactical greedy moves (depth 1), 25% random
  if (difficulty === 'EASY') {
    if (Math.random() < 0.25) {
      const idx = Math.floor(Math.random() * moves.length);
      return moves[idx].lan;
    }
    const { move } = minimax(chess, 1, -Infinity, Infinity, color === 'w', brain, chaosFactor);
    if (move) return move;
    return moves[0].lan;
  }

  // Medium mode: depth 2 search
  if (difficulty === 'MEDIUM') {
    const { move } = minimax(chess, 2, -Infinity, Infinity, color === 'w', brain, chaosFactor);
    if (move) return move;
    return moves[0].lan;
  }

  // Hard mode: depth 3 search
  if (difficulty === 'HARD') {
    const { move } = minimax(chess, 3, -Infinity, Infinity, color === 'w', brain, chaosFactor);
    if (move) return move;
    return moves[0].lan;
  }

  return moves[0].lan;
}

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 *
 * Engine 5: Autonomous ReAct Agent Loop & Step Dispatcher
 * Coordinates the spatiotemporal lifecycle, model adapter streaming,
 * sandboxed tool invocation, and trajectory recording.
 */

import { UnifiedModelAdapter } from './model-adapter';
import { SessionStateEngine } from './session-state';
import { ToolSandboxEngine } from './tool-sandbox';
import {
  AgentLoopConfig,
  AgentStatus,
  AgentStepTrajectory,
  ModelMessage,
  SpatiotemporalContext,
  ToolDefinition,
  ToolExecutionResult,
} from './types';

export interface AgentRunCallbacks {
  onStatusChange?: (status: AgentStatus) => void;
  onThoughtChunk?: (chunk: string) => void;
  onTextChunk?: (chunk: string) => void;
  onStepComplete?: (step: AgentStepTrajectory) => void;
}

export class AgentLoopEngine {
  private ctx: SpatiotemporalContext;
  private modelAdapter: UnifiedModelAdapter;
  private sandbox: ToolSandboxEngine;
  private session: SessionStateEngine;
  private config: AgentLoopConfig;
  private trajectory: AgentStepTrajectory[] = [];
  private currentStatus: AgentStatus = 'idle';

  constructor(
    ctx: SpatiotemporalContext,
    modelAdapter: UnifiedModelAdapter,
    sandbox: ToolSandboxEngine,
    session: SessionStateEngine,
    config: Partial<AgentLoopConfig> = {}
  ) {
    this.ctx = ctx;
    this.modelAdapter = modelAdapter;
    this.sandbox = sandbox;
    this.session = session;
    this.config = {
      maxSteps: config.maxSteps || 8,
      timeoutMs: config.timeoutMs || 60000,
      stopOnFirstFailure: config.stopOnFirstFailure || false,
      enableThinking: config.enableThinking !== undefined ? config.enableThinking : true,
      thinkingLevel: config.thinkingLevel || 'HIGH',
    };
  }

  public getStatus(): AgentStatus {
    return this.currentStatus;
  }

  public getTrajectory(): AgentStepTrajectory[] {
    return [...this.trajectory];
  }

  /**
   * Executes the autonomous multi-turn ReAct loop until task goal is achieved or limits reached.
   */
  public async executeTask(
    userPrompt: string,
    callbacks: AgentRunCallbacks = {}
  ): Promise<{ status: AgentStatus; trajectory: AgentStepTrajectory[]; finalOutput: string }> {
    this.trajectory = [];
    this.updateStatus('planning', callbacks);

    // Initialize root session context if not already set
    this.session.initRoot(
      'You are an autonomous engineering agent running in the DeepSeek Harness runtime environment. Use sandboxed tools systematically to achieve the goal.'
    );

    // Record user prompt
    this.session.appendMessage({
      role: 'user',
      content: userPrompt,
      timestamp: Date.now(),
    });

    const tools: ToolDefinition[] = this.sandbox.getStandardToolDefinitions();
    let stepNumber = 0;
    let finalOutput = '';

    while (stepNumber < this.config.maxSteps) {
      stepNumber++;
      const stepStartTime = Date.now();

      // Step scope context creation
      const stepCtx = this.ctx.extend('step');
      await this.ctx.emit('step:before', { stepNumber, prompt: userPrompt });

      this.updateStatus('thinking', callbacks);

      const history = this.session.getLinearHistory();
      let accumulatedThought = '';
      let accumulatedText = '';
      const pendingToolCalls: Array<{ id: string; name: string; args: Record<string, unknown> }> = [];

      try {
        const stream = this.modelAdapter.generateStream(history, tools, {
          model: 'deepseek-reasoner',
          thinkingLevel: this.config.thinkingLevel,
        });

        for await (const delta of stream) {
          if (delta.type === 'thought_chunk' && delta.deltaThought) {
            accumulatedThought += delta.deltaThought;
            callbacks.onThoughtChunk?.(delta.deltaThought);
            await this.ctx.emit('model:stream:thought', delta.deltaThought);
          } else if (delta.type === 'text_chunk' && delta.deltaText) {
            if (this.currentStatus !== 'streaming_response') {
              this.updateStatus('streaming_response', callbacks);
            }
            accumulatedText += delta.deltaText;
            callbacks.onTextChunk?.(delta.deltaText);
            await this.ctx.emit('model:stream:chunk', delta.deltaText);
          } else if (delta.type === 'tool_call_chunk' && delta.toolCall) {
            let parsedArgs: Record<string, unknown> = {};
            try {
              parsedArgs = delta.toolCall.deltaArgs ? JSON.parse(delta.toolCall.deltaArgs) : {};
            } catch {
              parsedArgs = { raw: delta.toolCall.deltaArgs };
            }
            pendingToolCalls.push({
              id: delta.toolCall.id,
              name: delta.toolCall.name || 'run_shell',
              args: parsedArgs,
            });
          }
        }
      } catch (err: any) {
        this.updateStatus('halted_error', callbacks);
        return {
          status: 'halted_error',
          trajectory: this.trajectory,
          finalOutput: `Engine failure during generation stream: ${err?.message || err}`,
        };
      }

      // Record Assistant message into session state
      const assistantMsg: ModelMessage = {
        role: 'assistant',
        content: accumulatedText,
        thought: accumulatedThought,
        timestamp: Date.now(),
      };
      this.session.appendMessage(assistantMsg);

      // Execute tool calls if any
      const toolResults: ToolExecutionResult[] = [];
      if (pendingToolCalls.length > 0) {
        this.updateStatus('executing_tools', callbacks);

        for (const tc of pendingToolCalls) {
          await this.ctx.emit('tool:invoke:before', tc);

          const result = await this.sandbox.executeToolCall(tc.id, tc.name, tc.args);
          toolResults.push(result);

          await this.ctx.emit('tool:invoke:after', result);

          // Append tool result message to conversation state
          this.session.appendMessage({
            role: 'tool',
            content: result.output,
            timestamp: Date.now(),
          });
        }

        // Apply context pruning if tokens exceed budget
        this.session.pruneContextIfNeeded();
      }

      const stepTrajectory: AgentStepTrajectory = {
        stepNumber,
        thought: accumulatedThought,
        modelOutput: accumulatedText,
        toolCalls: pendingToolCalls,
        toolResults,
        status: pendingToolCalls.length > 0 ? 'executing_tools' : 'completed',
        durationMs: Date.now() - stepStartTime,
        timestamp: Date.now(),
      };

      this.trajectory.push(stepTrajectory);
      callbacks.onStepComplete?.(stepTrajectory);
      await this.ctx.emit('step:after', stepTrajectory);
      await stepCtx.dispose();

      // If no tools were called, the agent has emitted its final response
      if (pendingToolCalls.length === 0) {
        finalOutput = accumulatedText;
        this.updateStatus('completed', callbacks);
        return {
          status: 'completed',
          trajectory: this.trajectory,
          finalOutput,
        };
      }
    }

    this.updateStatus('max_steps_exceeded', callbacks);
    return {
      status: 'max_steps_exceeded',
      trajectory: this.trajectory,
      finalOutput: finalOutput || 'Task halted: Maximum step budget reached without terminal condition.',
    };
  }

  private updateStatus(status: AgentStatus, callbacks: AgentRunCallbacks) {
    this.currentStatus = status;
    callbacks.onStatusChange?.(status);
  }
}

