/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 *
 * Engine 4: Session State & Tree-Structured Context Engine
 * Sanitized branching conversation tree, checkpoint rollbacks,
 * token accounting, and intelligent sliding-window pruning.
 */

import {
  ModelMessage,
  SessionTreeNode,
  TokenBudgetConfig,
} from './types';

export class SessionStateEngine {
  private nodes: Map<string, SessionTreeNode> = new Map();
  private rootId: string | null = null;
  private currentLeafId: string | null = null;
  private budgetConfig: TokenBudgetConfig;

  constructor(
    budgetConfig: Partial<TokenBudgetConfig> = {}
  ) {
    this.budgetConfig = {
      maxContextTokens: budgetConfig.maxContextTokens || 16384,
      reserveForGeneration: budgetConfig.reserveForGeneration || 4096,
      pruneThreshold: budgetConfig.pruneThreshold || 0.85,
      strategy: budgetConfig.strategy || 'hybrid',
    };
  }

  /**
   * Initializes a new conversation root.
   */
  public initRoot(systemPrompt: string): string {
    const rootNode: SessionTreeNode = {
      id: `node_root_${Date.now()}`,
      parentId: null,
      stepIndex: 0,
      message: {
        role: 'system',
        content: systemPrompt,
        timestamp: Date.now(),
      },
      stateSnapshot: {
        tokenCount: this.estimateTokens(systemPrompt),
        activeFiles: [],
      },
      childrenIds: [],
      createdAt: Date.now(),
    };

    this.nodes.set(rootNode.id, rootNode);
    this.rootId = rootNode.id;
    this.currentLeafId = rootNode.id;
    return rootNode.id;
  }

  /**
   * Appends a message to the active branch.
   */
  public appendMessage(
    message: ModelMessage,
    activeFiles: string[] = []
  ): SessionTreeNode {
    if (!this.currentLeafId) {
      this.initRoot('You are an autonomous harness agent.');
    }

    const parentNode = this.nodes.get(this.currentLeafId!)!;
    const msgTokens = this.estimateMessageTokens(message);

    const newNode: SessionTreeNode = {
      id: `node_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      parentId: parentNode.id,
      stepIndex: parentNode.stepIndex + 1,
      message,
      stateSnapshot: {
        tokenCount: msgTokens,
        activeFiles,
      },
      childrenIds: [],
      createdAt: Date.now(),
    };

    parentNode.childrenIds.push(newNode.id);
    this.nodes.set(newNode.id, newNode);
    this.currentLeafId = newNode.id;

    return newNode;
  }

  /**
   * Forks the active conversation from any historical node to explore speculative branches.
   */
  public fork(fromNodeId: string): string {
    if (!this.nodes.has(fromNodeId)) {
      throw new Error(`Node ${fromNodeId} not found in session tree.`);
    }
    this.currentLeafId = fromNodeId;
    return fromNodeId;
  }

  /**
   * Returns the linear trajectory of messages from root to the active leaf node.
   */
  public getLinearHistory(leafId = this.currentLeafId): ModelMessage[] {
    if (!leafId || !this.nodes.has(leafId)) return [];

    const history: ModelMessage[] = [];
    let curr: SessionTreeNode | null = this.nodes.get(leafId)!;

    while (curr) {
      history.unshift(curr.message);
      curr = curr.parentId ? this.nodes.get(curr.parentId) || null : null;
    }

    return history;
  }

  /**
   * Calculates total tokens in the current active linear context.
   */
  public getActiveContextTokens(): number {
    const history = this.getLinearHistory();
    return history.reduce((acc, m) => acc + this.estimateMessageTokens(m), 0);
  }

  /**
   * Evaluates if context exceeds threshold and applies pruning strategies.
   */
  public pruneContextIfNeeded(): { pruned: boolean; tokensBefore: number; tokensAfter: number; strategyUsed: string } {
    const tokensBefore = this.getActiveContextTokens();
    const threshold = this.budgetConfig.maxContextTokens * this.budgetConfig.pruneThreshold;

    if (tokensBefore <= threshold) {
      return { pruned: false, tokensBefore, tokensAfter: tokensBefore, strategyUsed: 'none' };
    }

    // Prune excessive tool outputs along the branch
    let currId = this.currentLeafId;
    let prunedCount = 0;

    while (currId) {
      const node = this.nodes.get(currId);
      if (!node) break;

      if (node.message.role === 'tool' && typeof node.message.content === 'string') {
        if (node.message.content.length > 500) {
          node.message.content = node.message.content.slice(0, 300) + '\n[...historical output pruned for context economy...]';
          prunedCount++;
        }
      }
      currId = node.parentId;
    }

    const tokensAfter = this.getActiveContextTokens();
    return {
      pruned: prunedCount > 0,
      tokensBefore,
      tokensAfter,
      strategyUsed: this.budgetConfig.strategy,
    };
  }

  /**
   * Approximate token counter (sanitized BPE heuristic: ~4 chars per token).
   */
  public estimateTokens(text: string): number {
    if (!text) return 0;
    return Math.ceil(text.length / 4);
  }

  private estimateMessageTokens(msg: ModelMessage): number {
    let count = 4; // overhead
    if (typeof msg.content === 'string') {
      count += this.estimateTokens(msg.content);
    } else if (Array.isArray(msg.content)) {
      for (const part of msg.content) {
        if (part.text) count += this.estimateTokens(part.text);
        if (part.toolCall) count += this.estimateTokens(JSON.stringify(part.toolCall));
        if (part.toolResult) count += this.estimateTokens(part.toolResult.content);
      }
    }
    if (msg.thought) {
      count += this.estimateTokens(msg.thought);
    }
    return count;
  }

  /**
   * Serializes current tree for persistence or snapshotting.
   */
  public exportSnapshot(): {
    rootId: string | null;
    currentLeafId: string | null;
    nodes: SessionTreeNode[];
  } {
    return {
      rootId: this.rootId,
      currentLeafId: this.currentLeafId,
      nodes: Array.from(this.nodes.values()),
    };
  }
}

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 *
 * Engine 1: Spatiotemporal Lifecycle & Plugin Kernel
 * Clean-room implementation of Cordis-inspired composability for agent harnesses.
 * Features hierarchical context scopes, service injection, and spatiotemporal event hooks.
 */

import {
  Disposable,
  HookHandler,
  LifecycleHookName,
  Plugin,
  PluginManifest,
  SpatiotemporalContext,
} from './types';

export class SpatiotemporalLifecycleContext implements SpatiotemporalContext {
  public readonly id: string;
  public readonly parent: SpatiotemporalContext | null;
  public readonly scope: 'global' | 'session' | 'step';

  private services: Map<string, unknown> = new Map();
  private hooks: Map<LifecycleHookName, Set<HookHandler<any>>> = new Map();
  private activePlugins: Map<string, Plugin<any>> = new Map();
  private disposables: Set<Disposable> = new Set();
  private isDisposed = false;

  constructor(
    scope: 'global' | 'session' | 'step' = 'global',
    parent: SpatiotemporalContext | null = null,
    customId?: string
  ) {
    this.id = customId || `${scope}_${Math.random().toString(36).substring(2, 9)}`;
    this.scope = scope;
    this.parent = parent;
  }

  /**
   * Register a dependency/service into this context scope.
   */
  public provide<T>(id: string, service: T): void {
    if (this.isDisposed) throw new Error(`Cannot provide service to disposed context ${this.id}`);
    this.services.set(id, service);
  }

  /**
   * Resolve a service by traversing up the context prototype hierarchy.
   */
  public inject<T>(id: string): T {
    if (this.services.has(id)) {
      return this.services.get(id) as T;
    }
    if (this.parent) {
      return this.parent.inject<T>(id);
    }
    throw new Error(`Service '${id}' not found in Spatiotemporal Context hierarchy [${this.id}]`);
  }

  /**
   * Check if a service is provided either in this context or any ancestor.
   */
  public has(id: string): boolean {
    if (this.services.has(id)) return true;
    return this.parent ? this.parent.has(id) : false;
  }

  /**
   * Subscribe to a spatiotemporal lifecycle event.
   */
  public on<T = unknown>(event: LifecycleHookName, handler: HookHandler<T>): Disposable {
    if (this.isDisposed) {
      return { dispose: () => {} };
    }

    if (!this.hooks.has(event)) {
      this.hooks.set(event, new Set());
    }

    const set = this.hooks.get(event)!;
    set.add(handler);

    const disposable: Disposable = {
      dispose: () => {
        set.delete(handler);
        this.disposables.delete(disposable);
      },
    };
    this.disposables.add(disposable);
    return disposable;
  }

  /**
   * Emit an event through the current context and propagate upward through the hierarchy.
   */
  public async emit<T = unknown>(event: LifecycleHookName, payload: T): Promise<void> {
    if (this.isDisposed) return;

    // Fire local handlers
    const handlers = this.hooks.get(event);
    if (handlers && handlers.size > 0) {
      const promises: Promise<void>[] = [];
      for (const handler of Array.from(handlers)) {
        try {
          const res = handler(payload, this);
          if (res instanceof Promise) {
            promises.push(res);
          }
        } catch (err) {
          console.error(`[LifecycleContext ${this.id}] Error in hook '${event}':`, err);
        }
      }
      if (promises.length > 0) {
        await Promise.allSettled(promises);
      }
    }

    // Propagate up to parent context
    if (this.parent) {
      await this.parent.emit(event, payload);
    }
  }

  /**
   * Dynamically mount a plugin with its configuration and track its lifecycle.
   */
  public plugin<TConfig>(plugin: Plugin<TConfig>, config?: TConfig): Disposable {
    if (this.isDisposed) throw new Error(`Cannot register plugin in disposed context ${this.id}`);

    if (this.activePlugins.has(plugin.name)) {
      console.warn(`[LifecycleContext] Plugin '${plugin.name}' already registered in context ${this.id}`);
    }

    this.activePlugins.set(plugin.name, plugin as Plugin<any>);

    try {
      const maybePromise = plugin.apply(this, config);
      if (maybePromise instanceof Promise) {
        maybePromise.catch((err) => {
          console.error(`[LifecycleContext] Plugin ${plugin.name} failed during async application:`, err);
        });
      }
    } catch (err) {
      console.error(`[LifecycleContext] Plugin ${plugin.name} failed to apply:`, err);
    }

    const disposable: Disposable = {
      dispose: () => {
        this.activePlugins.delete(plugin.name);
        this.disposables.delete(disposable);
      },
    };

    this.disposables.add(disposable);
    return disposable;
  }

  /**
   * Branch into a scoped child context with lexical inheritance.
   */
  public extend(scope: 'session' | 'step'): SpatiotemporalContext {
    return new SpatiotemporalLifecycleContext(scope, this);
  }

  /**
   * Teardown this context and all registered subscriptions.
   */
  public async dispose(): Promise<void> {
    if (this.isDisposed) return;
    this.isDisposed = true;

    for (const d of Array.from(this.disposables)) {
      try {
        await d.dispose();
      } catch (err) {
        console.error(`[LifecycleContext ${this.id}] Error during disposal:`, err);
      }
    }

    this.disposables.clear();
    this.hooks.clear();
    this.services.clear();
    this.activePlugins.clear();
  }

  public getActivePluginNames(): string[] {
    return Array.from(this.activePlugins.keys());
  }
}

/**
 * Creates the root spatiotemporal kernel context.
 */
export function createLifecycleKernel(): SpatiotemporalContext {
  return new SpatiotemporalLifecycleContext('global', null, 'kernel_root');
}

