export type PipelineStageId =
  | "stage0_ingestion"
  | "stage1_sanitization"
  | "stage2_reasoning"
  | "stage3_ast_gate"
  | "stage4_review"
  | "stage5_convergence";

export interface PipelineStageState {
  id: PipelineStageId;
  name: string;
  status: "pending" | "running" | "succeeded" | "blocked" | "skipped";
  summary: string;
  details?: Record<string, unknown>;
  durationMs?: number;
}

export interface PipelineConfig {
  githubToken?: string;
  targetRepo: string;
  targetBranch: string;
  evolutionBranch: string;
  filePath: string;
  userPrompt: string;
  siphonSourceId: string;
  code: string;
  triggeredBy?: "manual" | "autonomous" | "watch" | "continuous" | "scheduled";
}

export interface PipelineExecutionReport {
  id: string;
  timestamp: number;
  config: PipelineConfig;
  status: "COMPLETED" | "REJECTED" | "HALTED" | "SANITIZED_APPLIED";
  stages: Record<PipelineStageId, PipelineStageState>;
  originalCode: string;
  evolvedCode: string;
  patternVote: ArchitecturalVote;
  siphonVote?: ArchitecturalVote;
  sanitizerResult: SecuritySanitizerResult;
  agentEngineResult: EngineExecutionResult;
  astDiffResult: AstDiffResult;
  reviewVerdict: DebateVerdict;
  tribunalVerdict?: DebateVerdict;
  haltState: HaltEvaluationState | null;
  proofCommitHash: string;
  logs: Array<{
    timestamp: string;
    message: string;
    type: "info" | "warn" | "success" | "error";
  }>;
}

export type StageUpdateHandler = (stage: PipelineStageState) => void;
export type LogHandler = (log: {
  timestamp: string;
  message: string;
  type: "info" | "warn" | "success" | "error";
}) => void;

export class UnifiedPipelineRunner {
  private governor = new SelfStoppingGovernor({
    maxCycles: 100,
    maxConsecutiveFailures: 3,
  });

  public async runPipeline(
    config: PipelineConfig,
    onStageUpdate?: StageUpdateHandler,
    onLog?: LogHandler
  ): Promise<PipelineExecutionReport> {
    await emgRagInstance.ensureSeeded();

    const pipelineId = `helper_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    const logs: PipelineExecutionReport["logs"] = [];

    const log: LogHandler = (entry) => {
      logs.push(entry);
      if (onLog) onLog(entry);
    };

    const stages: Record<PipelineStageId, PipelineStageState> = {
      stage0_ingestion: {
        id: "stage0_ingestion",
        name: "0. Pattern Ingestion Helper",
        status: "pending",
        summary: "Waiting to initialize pattern sources",
      },
      stage1_sanitization: {
        id: "stage1_sanitization",
        name: "1. Security Sanitizer Helper",
        status: "pending",
        summary: "Waiting for credential and entropy scan",
      },
      stage2_reasoning: {
        id: "stage2_reasoning",
        name: "2. Modular Agent Helper",
        status: "pending",
        summary: "Waiting for bounded ReAct reasoning loop",
      },
      stage3_ast_gate: {
        id: "stage3_ast_gate",
        name: "3. AST Verification Helper",
        status: "pending",
        summary: "Waiting for AST symbol retention check",
      },
      stage4_review: {
        id: "stage4_review",
        name: "4. Code Review Helper",
        status: "pending",
        summary: "Waiting for dual-perspective review",
      },
      stage5_convergence: {
        id: "stage5_convergence",
        name: "5. Commit & Convergence Helper",
        status: "pending",
        summary: "Waiting for convergence evaluation",
      },
    };

    const updateStage = (
      stageId: PipelineStageId,
      status: PipelineStageState["status"],
      summary: string,
      details?: Record<string, unknown>,
      durationMs?: number
    ) => {
      stages[stageId] = { ...stages[stageId], status, summary, details, durationMs };
      if (onStageUpdate) onStageUpdate(stages[stageId]);
    };

    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[HELPER START] Target: ${config.targetRepo}:${config.filePath} (${config.targetBranch})`,
      type: "info",
    });

    // STAGE 0
    const t0 = performance.now();
    updateStage("stage0_ingestion", "running", "Analyzing target structure and selecting architectural pattern...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 0] Analyzing codebase patterns and selecting enhancement template...",
      type: "info",
    });

    const patternVote = performArchitecturalVote(config.filePath, config.code);
    const selectedSource =
      SIPHON_SOURCES.find(s => s.id === config.siphonSourceId) || patternVote.source;
    const dur0 = Math.round(performance.now() - t0);

    updateStage(
      "stage0_ingestion",
      "succeeded",
      "Ingestion complete — direct LLM refactor (no template selection)",
      { selectedSource, vote: patternVote },
      dur0
    );
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 0] No pattern classifier configured — ${config.filePath} goes straight to the LLM refactor.`,
      type: "info",
    });

    // STAGE 1
    const t1 = performance.now();
    updateStage("stage1_sanitization", "running", "Running Shannon entropy calculation and credential scan...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 1] Scanning buffers for credential leakage and high-entropy secrets...",
      type: "info",
    });

    const sanitizerResult = sanitizeAndGovern(config.code, config.filePath);
    const dur1 = Math.round(performance.now() - t1);

    if (sanitizerResult.clean) {
      updateStage(
        "stage1_sanitization",
        "succeeded",
        "Clean: 0 hardcoded credentials or high-entropy secrets detected.",
        { violations: [] },
        dur1
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: "[STAGE 1] Pre-screen passed: 0 credentials leaked.",
        type: "success",
      });
    } else {
      updateStage(
        "stage1_sanitization",
        "succeeded",
        `Sanitized ${sanitizerResult.violations.length} secret token(s) prior to execution.`,
        { violations: sanitizerResult.violations },
        dur1
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 1] Sanitized ${sanitizerResult.violations.length} high-entropy token(s). Redactions applied.`,
        type: "warn",
      });
    }

    const sanitizedBaseCode = sanitizerResult.sanitizedCode;

    // STAGE 2
    const t2 = performance.now();
    updateStage("stage2_reasoning", "running", "Running bounded ReAct loop with in-memory VFS sandbox...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 2] Executing modular agent loop for: "${config.userPrompt.slice(0, 60)}..."`,
      type: "info",
    });

    // Fetch per-file postmortem constraints (if any prior failures recorded)
    const postmortemConstraints = await postmortemStore.getConstraintsForFile(
      config.targetRepo,
      config.targetBranch,
      config.filePath
    );
    if (postmortemConstraints.hasActivePostmortem) {
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 2] Active postmortem found (${postmortemConstraints.failureType}, ${postmortemConstraints.attempts} prior failure(s)). Injecting constraints into LLM prompt.`,
        type: "warn",
      });
    }

    const agentGoal = `${config.userPrompt} (Template: ${selectedSource.label})`;
    const agentEngineResult = await executeCleanRoomEngine("inference-reasoning-loop", agentGoal, {
      originalCode: sanitizedBaseCode,
      filePath: config.filePath,
      postmortemConstraints: postmortemConstraints.promptBlock,
    });
    const dur2 = Math.round(performance.now() - t2);

    const llmStatus = agentEngineResult.llmUsed
      ? `LLM refactor produced ${agentEngineResult.proposedEvolvedCode.length} bytes (${agentEngineResult.llmTotalLatencyMs}ms).`
      : `LLM unavailable (${agentEngineResult.llmError ?? "unknown"}). No refactor produced — original code kept, cycle will halt at 0-diff.`;

    updateStage(
      "stage2_reasoning",
      "succeeded",
      `Completed in ${agentEngineResult.steps.length} bounded steps. ${llmStatus}`,
      {
        steps: agentEngineResult.steps.length,
        tokenBudget: agentEngineResult.tokenBudget,
        llmUsed: agentEngineResult.llmUsed,
        llmLatencyMs: agentEngineResult.llmTotalLatencyMs,
      },
      dur2
    );
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 2] Agent loop completed (${agentEngineResult.steps.length} steps). ${llmStatus}`,
      type: agentEngineResult.llmUsed ? "success" : "warn",
    });

    // Synthesize proposed evolved code.
    // The LLM's refactored output IS the enhancement — we do NOT prepend a
    // "Enhanced by Architecture Helper Pipeline" header. That header was
    // cosmetic noise that polluted every committed file without adding
    // value. If the LLM produced no semantic change, we return the
    // original code unchanged and let the 0-diff saturation check halt
    // the cycle (no commit = no noise).

    let evolvedCode: string;
    if (agentEngineResult.llmUsed && agentEngineResult.proposedEvolvedCode.trim()) {
      // Real LLM-produced code — sanitize it again (defense in depth)
      // and use it AS-IS. No header prepended.
      const llmCode = agentEngineResult.proposedEvolvedCode;
      const reSanitized = sanitizeAndGovern(llmCode, config.filePath);
      evolvedCode = reSanitized.sanitizedCode;
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 2] Using LLM-refactored code (${llmCode.length} bytes, re-sanitized: ${reSanitized.violations.length} violations).`,
        type: reSanitized.clean ? "success" : "warn",
      });
    } else {
      // LLM unavailable or produced no code — return the original
      // unchanged. The 0-diff saturation check will halt this cycle
      // (no semantic change = nothing to commit). We do NOT inject a
      // cosmetic header or unused ExecutionContract interface.
      evolvedCode = sanitizedBaseCode;
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 2] No LLM refactor produced. Returning original code unchanged (no cosmetic header injected).`,
        type: "warn",
      });
    }

    // STAGE 3
    const t3 = performance.now();
    updateStage("stage3_ast_gate", "running", "Verifying AST symbol retention and structural drift...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 3] Evaluating AST symbol retention ratio and syntax invariants...",
      type: "info",
    });

    // The AST gate measures the LLM's diff — compare against the
    // SANITIZED base (the refactor stage's actual input), not the raw
    // original. (The old baseline attributed sanitizer redaction deltas
    // — [REDACTED_*] injections — to the "LLM refactor".)
    // Replace ②: the gate invocation itself lives in core/gate-runner.ts.
    // This stage-local slice runs ONLY the AST gate (score tolerance,
    // REMOTE_PATH_POLICY) — the guard runs at stage 4 because the 0-diff
    // short-circuit below must sit between them (an identical-code cycle
    // spends no guard or tribunal time at all).
    const astChain = await runGateChain({
      filePath: config.filePath,
      originalCode: config.code,
      astBaselineCode: sanitizedBaseCode,
      evolvedCode,
      policy: { ...REMOTE_PATH_POLICY, guard: false },
    });
    const astDiffResult = astChain.ast;
    if (!astDiffResult) {
      // Unreachable under REMOTE_PATH_POLICY (ast: true) — this guards
      // the type, not the runtime.
      throw new Error("gate-runner returned no AST result under policy.ast=true");
    }
    const dur3 = Math.round(performance.now() - t3);

    if (astDiffResult.passed) {
      updateStage(
        "stage3_ast_gate",
        "succeeded",
        `Passed: AST Score ${astDiffResult.astScore}/100, Retained ${astDiffResult.symbolMap.retainedCount}/${astDiffResult.symbolMap.originalCount} symbols (${astDiffResult.parserUsed}).`,
        {
          astScore: astDiffResult.astScore,
          violations: astDiffResult.violations,
          parserUsed: astDiffResult.parserUsed,
          symbolMap: astDiffResult.symbolMap,
          drift: astDiffResult.structuralDriftRatio,
        },
        dur3
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 3] AST verification passed with score ${astDiffResult.astScore}/100.`,
        type: "success",
      });
    } else {
      updateStage(
        "stage3_ast_gate",
        "blocked",
        `AST integrity check flagged violations (Score: ${astDiffResult.astScore}/100, ${astDiffResult.parserUsed}).`,
        {
          violations: astDiffResult.violations,
          parserUsed: astDiffResult.parserUsed,
          symbolMap: astDiffResult.symbolMap,
          drift: astDiffResult.structuralDriftRatio,
        },
        dur3
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 3] AST violations flagged: ${astDiffResult.violations.map(v => v.code).join(", ")}`,
        type: "warn",
      });
    }

    // STAGE 4
    const t4 = performance.now();

    // 0-diff short-circuit: if the evolution stage produced NO change
    // relative to its ACTUAL input (the sanitized base), there is nothing
    // to review and nothing to commit. (The old check compared against
    // the RAW config.code — when the sanitizer had redacted secrets from
    // the base, a sanitizer-only rewrite masqueraded as an "evolution"
    // and sailed through the gates to a commit.) Convening a tribunal
    // over identical code proves nothing — report HALTED honestly and
    // stop here.
    if (evolvedCode === sanitizedBaseCode) {
      updateStage(
        "stage4_review",
        "skipped",
        "Skipped: 0-diff (no change produced). Nothing to review or commit.",
        { consensus: "SKIPPED_ZERO_DIFF" },
        Math.round(performance.now() - t4)
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: "[STAGE 4] Skipped — 0-diff: the evolution stage produced no change. Halting cycle honestly (no review, no commit).",
        type: "warn",
      });

      let haltStateEarly: HaltEvaluationState | null = null;
      try {
        haltStateEarly = this.governor.checkZeroDiffSaturation(sanitizedBaseCode, evolvedCode);
      } catch {
        haltStateEarly = null;
      }

      updateStage(
        "stage5_convergence",
        "succeeded",
        "Converged at 0-diff (saturation). No proof commit — nothing changed.",
        { proofCommitHash: "NONE", haltState: haltStateEarly },
        0
      );

      return {
        id: pipelineId,
        timestamp: Date.now(),
        config,
        status: "HALTED",
        stages,
        originalCode: config.code,
        evolvedCode,
        patternVote,
        siphonVote: patternVote,
        sanitizerResult,
        agentEngineResult,
        astDiffResult,
        reviewVerdict: {
          currentTopic: `Code Review for ${config.filePath}`,
          consensus: "APPROVED", // vacuous: identical code — nothing was changed, so nothing needs review
          consensusCoefficient: 1,
          cognitiveFriction: 0,
          securityPoints: [],
          architecturePoints: [],
          leadSummary: "Review skipped: 0-diff (no change produced).",
          arguments: [],
        },
        haltState: haltStateEarly,
        proofCommitHash: "NONE",
        logs,
      };
    }

    updateStage("stage4_review", "running", "Running mutation guard (triage + finalAuthority) before convening the review tribunal...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 4] Mutation guard: scanning proposed code for escape attempts and protected-path violations...",
      type: "info",
    });

    // ── Two-authority mutation guard (concept: Aether_Forge Ω repo) ────
    // Run BEFORE the debate tribunal: an obviously-evil proposal (newly-
    // introduced eval/child_process, or a mutation of a protected
    // scaffolding path) is rejected here without spending an LLM review
    // call. The guard is fail-CLOSED: triage evil → reject; unsure/good →
    // finalAuthority (protected paths + non-empty). See mutation-guard.ts.
    // Replace ②: invoked through core/gate-runner.ts (stage-local slice:
    // guard only — the AST gate already ran at stage 3). The runner
    // normalizes the guard path centrally, so an absolute-path caller can
    // no longer bypass the protected-path check.
    const guardChain = await runGateChain({
      filePath: config.filePath,
      originalCode: config.code,
      evolvedCode,
      policy: { ...REMOTE_PATH_POLICY, ast: false },
    });
    const gateResult = guardChain.guard;
    if (!gateResult) {
      // Unreachable under REMOTE_PATH_POLICY (guard: true) — guards the
      // type, not the runtime.
      throw new Error("gate-runner returned no guard result under policy.guard=true");
    }
    if (!gateResult.allowed) {
      const dur4guard = Math.round(performance.now() - t4);
      const rejectMsg = `Mutation guard REJECTED (${gateResult.rejectedBy}): ${gateResult.reasons.join("; ")}`;
      updateStage(
        "stage4_review",
        "blocked",
        rejectMsg,
        {
          consensus: "MUTATION_GUARD_REJECTED",
          rejectedBy: gateResult.rejectedBy,
          triageVerdict: gateResult.verdict,
          triageSuspicion: gateResult.triage.suspicionScore,
          reasons: gateResult.reasons,
        },
        dur4guard
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 4] ${rejectMsg}`,
        type: "error",
      });
      // Synthesize a review verdict that the downstream gate logic reads
      // as REJECTED, so the cycle halts with no commit. We do NOT call
      // the debate tribunal — the guard already decided, and spending
      // an LLM call on an evil proposal would waste quota + risk the LLM
      // being talked into approving it.
      const rejectedVerdict: DebateVerdict = {
        currentTopic: `Mutation Guard for ${config.filePath}`,
        consensus: "REJECTED",
        consensusCoefficient: 0,
        cognitiveFriction: 1,
        securityPoints: gateResult.reasons,
        architecturePoints: [],
        leadSummary: `Mutation guard rejected before review: ${gateResult.rejectedBy} layer.`,
        arguments: [],
      };
      // Record the guard-rejection as a postmortem so the next attempt
      // gets the constraint — the LLM will see "you tried to introduce
      // eval( last time; don't" in its prompt.
      try {
        await postmortemStore.recordFailure({
          repo: config.targetRepo,
          branch: config.targetBranch,
          filePath: config.filePath,
          failureType: "OTHER",
          symptom: `Mutation guard rejected (${gateResult.rejectedBy})`,
          evidence: gateResult.reasons.join("\n"),
          constraints: [
            "The mutation guard rejected your last proposed change.",
            "Do NOT introduce any of: eval(, new Function(, child_process, __import__(,",
            "  require('fs'/'child_process'/'net'/'os'), fetch() to non-allowlisted hosts,",
            "  path-traversal literals (../../), process.mainModule, weak crypto (md5/sha1).",
            "Do NOT mutate protected paths: prisma/schema.prisma, package.json,",
            "  next.config.*, tsconfig.json, .env, Caddyfile, start-dev.sh, or any file",
            "  in the loop runtime / gates / LLM wrappers / UI control surface.",
          ].join("\n"),
        });
      } catch {
        /* best-effort — the rejection still blocks the commit */
      }
      // Fall through to STAGE 5 with the synthesized REJECTED verdict so
      // the normal "review rejected → no commit" path handles it.
      const reviewVerdict = rejectedVerdict;

      updateStage(
        "stage4_review",
        "blocked",
        `Mutation guard: ${gateResult.rejectedBy} rejected. Review skipped (no LLM call spent on a guarded proposal).`,
        {
          consensus: reviewVerdict.consensus,
          coefficient: reviewVerdict.consensusCoefficient,
          usedLlm: false,
          guardRejected: true,
          reasons: gateResult.reasons,
        },
        dur4guard
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 4] Mutation guard rejected — review tribunal skipped (no LLM call). Verdict: REJECTED.`,
        type: "warn",
      });

      // Skip to STAGE 5 convergence with the synthesized verdict.
      // (Mirrors the structure of the 0-diff early-return above, but
      // with a REJECTED verdict instead of a vacuous APPROVED one.)
      const t5guard = performance.now();
      const guardHaltState = this.governor.recordResult(false, config.filePath);
      const guardProofHash = await binaryShieldInstance
        .computeHash(evolvedCode)
        .then((h) => h.slice(0, 7))
        .catch(() => "UNPROVEN");
      updateStage(
        "stage5_convergence",
        "succeeded",
        `Converged (guard-rejected). Proof: ${guardProofHash}.`,
        { proofCommitHash: guardProofHash, haltState: guardHaltState, guardRejected: true },
        Math.round(performance.now() - t5guard)
      );

      emgRagInstance.addEntry({
        provenance: "failure",
        trust: "low",
        filePath: config.filePath,
        content: `Mutation guard rejected ${config.filePath} (${gateResult.rejectedBy}): ${gateResult.reasons.join("; ")}. Proof ${guardProofHash}.`,
        diagnosis: "MUTATION_GUARD_REJECTED",
      });

      let finalStatusGuard: PipelineExecutionReport["status"] = "REJECTED";
      if (guardHaltState && guardHaltState.shouldHalt) finalStatusGuard = "HALTED";

      return {
        id: pipelineId,
        timestamp: Date.now(),
        config,
        status: finalStatusGuard,
        stages,
        originalCode: config.code,
        evolvedCode,
        patternVote,
        siphonVote: patternVote,
        sanitizerResult,
        agentEngineResult,
        astDiffResult,
        reviewVerdict,
        tribunalVerdict: reviewVerdict,
        haltState: guardHaltState,
        proofCommitHash: guardProofHash,
        logs,
      };
    }

    // Guard passed — proceed to the LLM debate tribunal.
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 4] Mutation guard passed (triage: ${gateResult.verdict}, suspicion ${gateResult.triage.suspicionScore.toFixed(2)}). Convening review tribunal...`,
      type: "info",
    });

    updateStage("stage4_review", "running", "Conducting dual-perspective review (Security vs Architecture)...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 4] Convening LLM review tribunal: Security Reviewer vs Architecture Reviewer...",
      type: "info",
    });

    // The tribunal THROWS when the LLM is unavailable — no fabricated
    // verdicts. An unavailable review means the stage is blocked: the file
    // does not pass review, and that is reported honestly.
    let debateResult: Awaited<ReturnType<typeof conductLlmDebate>>;
    try {
      debateResult = await conductLlmDebate(
        `Code Review for ${config.filePath}`,
        evolvedCode,
        config.filePath
      );
    } catch (debateErr) {
      const dur4 = Math.round(performance.now() - t4);
      updateStage(
        "stage4_review",
        "blocked",
        `Review tribunal UNAVAILABLE — no verdict (LLM failure). Blocking: unreviewed code cannot pass.`,
        { consensus: "UNAVAILABLE", usedLlm: false, llmError: (debateErr as Error).message },
        dur4
      );
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 4] Review tribunal unavailable: ${(debateErr as Error).message.slice(0, 150)} — stage blocked, no fabrication`,
        type: "error",
      });
      throw debateErr;
    }
    const reviewVerdict = debateResult.verdict;
    const dur4 = Math.round(performance.now() - t4);
    const isReviewApproved =
      reviewVerdict.consensus === "APPROVED" ||
      reviewVerdict.consensus === "CONDITIONAL_APPROVAL";

    updateStage(
      "stage4_review",
      isReviewApproved ? "succeeded" : "blocked",
      `Verdict: ${reviewVerdict.consensus} (Consensus: ${(reviewVerdict.consensusCoefficient * 100).toFixed(0)}%) [LLM]`,
      {
        consensus: reviewVerdict.consensus,
        coefficient: reviewVerdict.consensusCoefficient,
        usedLlm: true,
      },
      dur4
    );
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 4] Review outcome: ${reviewVerdict.consensus} (${reviewVerdict.leadSummary}) [LLM]`,
      type: isReviewApproved ? "success" : "warn",
    });

    // STAGE 5
    const t5 = performance.now();
    updateStage("stage5_convergence", "running", "Verifying convergence and generating proof commit...");
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: "[STAGE 5] Checking 0-diff code saturation and computing proof commit hash...",
      type: "info",
    });

    const zeroDiffCheck = this.governor.checkZeroDiffSaturation(sanitizedBaseCode, evolvedCode);
    let haltState = zeroDiffCheck;

    if (zeroDiffCheck) {
      log({
        timestamp: new Date().toLocaleTimeString(),
        message: `[STAGE 5] Saturation check triggered: ${zeroDiffCheck.detail}`,
        type: "warn",
      });
    } else {
      const recordHalt = this.governor.recordResult(astDiffResult.passed, config.filePath);
      if (recordHalt) {
        haltState = recordHalt;
        log({
          timestamp: new Date().toLocaleTimeString(),
          message: `[STAGE 5] Loop convergence guard engaged: ${recordHalt.detail}`,
          type: "warn",
        });
      }
    }

    // Proof hash: computed from the ACTUAL evolved code. If hashing fails,
    // the proof is UNPROVEN — never a fabricated timestamp-based hash posing
    // as a proof commit (that would make the proof layer meaningless).
    const proofCommitHash = await binaryShieldInstance
      .computeHash(evolvedCode)
      .then(h => h.slice(0, 7))
      .catch(() => "UNPROVEN");
    const dur5 = Math.round(performance.now() - t5);

    // Record the run in RAG memory — HONESTLY (audit 2): a run that failed
    // the AST gate is a FAILURE pattern, not a validated clean one. This
    // used to write provenance:"clean" / trust:"high" unconditionally, so
    // rejected code entered topFixes() as a high-trust pattern that later
    // runs were encouraged to imitate.
    const runPassed = astDiffResult.passed;
    emgRagInstance.addEntry({
      provenance: runPassed ? "clean" : "failure",
      trust: runPassed ? "high" : "low",
      filePath: config.filePath,
      content: `Code Refactoring Helper run for ${config.filePath}. AST Score: ${astDiffResult.astScore}, Proof Hash: ${proofCommitHash}${runPassed ? "" : ", AST gate: FAILED"}`,
      cleanSnippet: runPassed ? evolvedCode.slice(0, 150) : undefined,
      diagnosis: `Review: ${reviewVerdict.consensus}`,
    });

    updateStage(
      "stage5_convergence",
      "succeeded",
      `Converged. Generated proof commit: ${proofCommitHash}`,
      { proofCommitHash, haltState },
      dur5
    );
    log({
      timestamp: new Date().toLocaleTimeString(),
      message: `[STAGE 5] Helper pipeline finished. Clean Proof Commit Hash: ${proofCommitHash}`,
      type: "success",
    });

    let finalStatus: PipelineExecutionReport["status"] = "COMPLETED";
    if (!astDiffResult.passed || reviewVerdict.consensus === "REJECTED") {
      finalStatus = "REJECTED";
    } else if (haltState && haltState.shouldHalt) {
      finalStatus = "HALTED";
    } else if (!sanitizerResult.clean) {
      finalStatus = "SANITIZED_APPLIED";
    }

    return {
      id: pipelineId,
      timestamp: Date.now(),
      config,
      status: finalStatus,
      stages,
      originalCode: config.code,
      evolvedCode,
      patternVote,
      siphonVote: patternVote,
      sanitizerResult,
      agentEngineResult,
      astDiffResult,
      reviewVerdict,
      tribunalVerdict: reviewVerdict,
      haltState,
      proofCommitHash,
      logs,
    };
  }

  public resetGovernor(): void {
    this.governor.reset();
  }

  /** Live governor counters — the health probe reports these instead of
   *  an asserted "ready" string. */
  public getGovernorStats(): {
    currentCycle: number;
    maxCycles: number;
    consecutiveFailures: number;
    maxConsecutiveFailures: number;
  } {
    return {
      currentCycle: this.governor.getCurrentCycle(),
      maxCycles: this.governor.getMaxCycles(),
      consecutiveFailures: this.governor.getConsecutiveFailures(),
      maxConsecutiveFailures: this.governor.getMaxConsecutiveFailures(),
    };
  }

  public setMaxCycles(max: number): void {
    this.governor.setMaxCycles(max);
  }

  public getGovernorCycles(): { current: number; max: number } {
    return {
      current: this.governor.getCurrentCycle(),
      max: this.governor.getMaxCycles(),
    };
  }
}

// Pin the singleton on globalThis (same pattern as the Prisma client):
// Turbopack gives each route its own module graph, and WITHOUT the pin
// the remote loop, the manual /api/pipeline/run route, and /api/health
// each got their OWN runner — three governors, three saturation banks,
// and the health probe reporting a different governor than the loop's.
// hot-swap clears this pin (GLOBAL_PINS) so a swap recreates the runner
// with the new code.
const runnerGlobal = globalThis as unknown as {
  __unifiedPipelineRunner?: UnifiedPipelineRunner;
};
export const unifiedPipelineRunnerInstance: UnifiedPipelineRunner =
  runnerGlobal.__unifiedPipelineRunner ??
  (runnerGlobal.__unifiedPipelineRunner = new UnifiedPipelineRunner());

/**
 * Sandbox test runner — the full closure of external-audit finding 1.
 *
 * The audit's PRIMARY defect: the test gate wrote the candidate mutation to
 * the LIVE file so `bun test` could import it. During the test window:
 *   - Turbopack could hot-reload the unverified candidate into the app.
 *   - A process crash could strand it on disk (the write-ahead journal in
 *     test-gate-journal.ts fixed the stranding, but the exposure window
 *     itself remained — a journal restores AFTER the damage window opened).
 *
 * This module eliminates the live-write entirely. The candidate NEVER
 * touches the real tree. Instead:
 *
 *   1. A throwaway copy of the project skeleton is built at
 *      <root>/.loop-sandbox/verify-XXXX/: src/ tree, tsconfig.json,
 *      package.json, prisma/ (the detectProjectRoot markers), a symlink to
 *      the real node_modules/ (dependency resolution without a 300MB copy),
 *      and — when the SQLite DB is small — a COPY of the DB with .env
 *      rewritten so tests that touch Prisma write to the sandbox DB, not
 *      the live one.
 *   2. The overlay files (the candidate mutation, or a newly drafted test)
 *      are written INTO the sandbox at their project-relative paths.
 *   3. `bun test` runs with cwd = the sandbox. Relative imports, the `@/`
 *      alias (tsconfig paths), and node_modules all resolve inside the
 *      sandbox; anything reading PROJECT_ROOT (core/paths.ts) resolves to
 *      the sandbox because the markers are there — modules under test
 *      operate on the candidate tree, never on the live one.
 *   4. The sandbox is deleted on every exit path, and only ever removed if
 *      it really lives under .loop-sandbox/ (paranoia guard on rmSync).
 *
 * Consequences, vs the audit's three bullets:
 *   - Turbopack can NOT observe the candidate (it never leaves the sandbox,
 *     which sits outside src/ and is gitignored).
 *   - The app can NOT hot-reload it (same reason).
 *   - A crash can NOT strand it (the sandbox is disposable; nothing in the
 *     live tree was ever modified). The crash journal stays armed as
 *     defense-in-depth for legacy states and any future code path that
 *     reintroduces live writes — see test-gate-journal.ts.
 *
 * Fail-closed: if the sandbox cannot be built or the runner errors, the
 * result is passed:false. A mutation we could not test is a rejected
 * mutation — never a silently-passed one (audit finding 2's principle).
 *
 * Pure leaf module: fs/path/child_process only. Lives under core/ — a
 * PROTECTED_PREFIX (audit 3) — so the loop can never weaken its own
 * isolation. No DB, no LLM, no pipeline imports (paths.ts is the sole
 * exception: it is itself a protected pure leaf).
 */

import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
  symlinkSync,
  writeFileSync,
} from "fs";
import { join, relative, isAbsolute } from "path";
import { spawn } from "child_process";
import { PROJECT_ROOT } from "./paths";

export interface SandboxOverlay {
  /** Absolute REAL path of the file being overridden in the sandbox. */
  path: string;
  /** The content to place at the sandbox location instead. */
  content: string;
}

export interface SandboxTestResult {
  passed: boolean;
  reason: string;
  testCount: number;
}

/** Where sandboxes live. Outside src/ (Turbopack never watches it),
 * gitignored (git add -A can never sweep it), wiped per run. */
const SANDBOX_PARENT = join(PROJECT_ROOT, ".loop-sandbox");

/** DBs larger than this are not copied — the sandbox falls back to the
 * real DATABASE_URL (behavioral parity with the pre-sandbox test runs)
 * rather than burning disk/time per verification. 32MB is ~100x the
 * current db/custom.db. */
const MAX_DB_COPY_BYTES = 32 * 1024 * 1024;

/** Build the sandbox skeleton. Returns the sandbox root, or null when a
 * mandatory piece is missing (caller fails closed on null). */
function buildSandbox(): { root: string; dbOverride?: string } | null {
  mkdirSync(SANDBOX_PARENT, { recursive: true });
  const root = mkdtempSync(join(SANDBOX_PARENT, "verify-"));

  try {
    // Project skeleton: the src tree + the files that make the sandbox a
    // self-consistent "project root" for bun (tsconfig paths), tsc
    // (tsconfig include), and core/paths.ts (package.json + prisma markers).
    cpSync(join(PROJECT_ROOT, "src"), join(root, "src"), { recursive: true });
    cpSync(join(PROJECT_ROOT, "tsconfig.json"), join(root, "tsconfig.json"));
    cpSync(join(PROJECT_ROOT, "package.json"), join(root, "package.json"));
    cpSync(join(PROJECT_ROOT, "prisma"), join(root, "prisma"), { recursive: true });

    // Dependencies resolve through a symlink — no node_modules copy.
    symlinkSync(join(PROJECT_ROOT, "node_modules"), join(root, "node_modules"), "dir");

    // DB isolation: rewrite DATABASE_URL to a sandbox copy when possible so
    // tests that write through Prisma mutate the disposable DB, not the
    // live one. Audit 3 (F11): the old fallback when the copy was skipped
    // (DB >32MB — it is already 178MB — unreadable, or .env unparseable)
    // was to INHERIT the real URL, so LLM-drafted tests executed against
    // PRODUCTION data. Now the fallback is a blank sandbox DB file: a
    // DB-dependent test FAILS (missing tables) and the gate rejects the
    // candidate — fail-closed isolation instead of silent live-DB access.
    let dbOverride: string | undefined;
    let dbIsolated = false;
    try {
      const envSrc = readFileSync(join(PROJECT_ROOT, ".env"), "utf-8");
      const m = envSrc.match(/^DATABASE_URL=file:(.+)$/m);
      if (m) {
        const raw = m[1].trim();
        const dbPath = isAbsolute(raw) ? raw : join(PROJECT_ROOT, raw);
        if (existsSync(dbPath)) {
          const size = statSync(dbPath).size;
          if (size <= MAX_DB_COPY_BYTES) {
            const rel = relative(PROJECT_ROOT, dbPath);
            // Only copy DBs that live inside the project (a DB elsewhere on
            // disk belongs to the environment, not to this repo).
            if (rel && !rel.startsWith("..")) {
              const sandboxDb = join(root, rel);
              mkdirSync(join(sandboxDb, ".."), { recursive: true });
              cpSync(dbPath, sandboxDb);
              // WAL mode keeps recent commits in -wal/-shm sidecars — copy
              // them too when present, or the sandbox DB is a stale snapshot.
              for (const suffix of ["-wal", "-shm"]) {
                const sidecar = `${dbPath}${suffix}`;
                if (existsSync(sidecar)) {
                  try {
                    cpSync(sidecar, `${sandboxDb}${suffix}`);
                  } catch {
                    /* sidecar vanished mid-copy (checkpoint race) — the main
                       file copy still stands; worst case is a stale snapshot */
                  }
                }
              }
              dbOverride = `file:${sandboxDb}`;
              // Also write a sandbox .env: anything that reads the file
              // directly (rather than process.env) gets the same override.
              const envSandbox = envSrc.replace(
                /^DATABASE_URL=file:.+$/m,
                `DATABASE_URL=${dbOverride}`
              );
              writeFileSync(join(root, ".env"), envSandbox, "utf-8");
              dbIsolated = true;
            }
          }
        }
      }
    } catch {
      // No .env / unreadable / copy failed — fall through to the blank-DB
      // isolation below (audit 3: never inherit the live URL).
    }
    if (!dbIsolated) {
      // Audit 3 (F11): FAIL-CLOSED isolation — point the sandbox at a BLANK
      // DB file inside the sandbox. Prisma opens it (creating an empty
      // SQLite file), and any query fails with "table does not exist" →
      // the test fails → the candidate is rejected. DB-independent tests
      // still pass, so this only rejects mutations whose tests genuinely
      // need production data (which must never be touched).
      const blankDb = join(root, "db", "sandbox-blank.db");
      try {
        mkdirSync(join(root, "db"), { recursive: true });
        writeFileSync(blankDb, "", { flag: "w" });
        dbOverride = `file:${blankDb}`;
        try {
          const envSrc2 = readFileSync(join(PROJECT_ROOT, ".env"), "utf-8");
          writeFileSync(
            join(root, ".env"),
            envSrc2.replace(/^DATABASE_URL=file:.+$/m, `DATABASE_URL=${dbOverride}`),
            "utf-8"
          );
        } catch {
          writeFileSync(join(root, ".env"), `DATABASE_URL=${dbOverride}\n`, "utf-8");
        }
        console.warn(
          `[SANDBOX] live DB too large/unreadable for copy — using BLANK isolated DB (${blankDb}). ` +
            `DB-dependent tests will fail by design (fail-closed isolation, audit 3 F11).`
        );
      } catch {
        // Could not even create the blank file — run with NO override but
        // an explicitly nulled DATABASE_URL so Prisma fails fast rather
        // than silently connecting to production.
        dbOverride = "file:/nonexistent-sandbox-db-fail-closed.db";
      }
    }

    return { root, dbOverride };
  } catch {
    // Setup failure must not leak a half-built sandbox.
    safeRemoveSandbox(root);
    return null;
  }
}

/** Delete a sandbox — but ONLY if it is really under SANDBOX_PARENT.
 * A path-handling bug must never turn this into `rm -rf` on the project. */
function safeRemoveSandbox(root: string): void {
  const rel = relative(SANDBOX_PARENT, root);
  if (rel.startsWith("..") || isAbsolute(rel)) return; // not ours — refuse
  try {
    rmSync(root, { recursive: true, force: true });
  } catch {
    /* best-effort: a stale sandbox dir is garbage-collected by nothing,
       but it is gitignored and outside src/ — it cannot affect the app. */
  }
}

/** Child env: inherit everything, override DATABASE_URL when the sandbox
 * has an isolated DB copy. process.env inside the dev server already
 * carries the REAL url (Next.js loads .env at boot), so the explicit
 * override is what actually redirects Prisma to the sandbox DB. */
function childEnv(dbOverride?: string): NodeJS.ProcessEnv {
  if (!dbOverride) return process.env;
  return { ...process.env, DATABASE_URL: dbOverride };
}

/** Map a real absolute path to its location inside the sandbox. Throws if
 * the path escapes the project root — overlays/tests must be project files. */
function sandboxPath(sandboxRoot: string, realPath: string): string {
  const rel = relative(PROJECT_ROOT, realPath);
  if (!rel || rel.startsWith("..") || isAbsolute(rel)) {
    throw new Error(`refusing to map out-of-project path: ${realPath}`);
  }
  return join(sandboxRoot, rel);
}

/** Async child runner — the non-blocking replacement for this module's
 *  spawnSync calls. spawnSync blocked the shared server event loop for the
 *  child's full runtime (up to 120s for a sandbox `tsc --noEmit`); `spawn` +
 *  Promise yields the loop back to HTTP handlers while the child works.
 *  Same { status, stdout, stderr } contract as spawnSync — fail-closed
 *  (status null on kill/error/timeout) so callers' `status !== 0` checks
 *  behave identically.
 *
 *  Inlined here (not imported from core/async-spawn) to preserve this
 *  module's pure-leaf import invariant: fs/path/child_process + paths.ts
 *  only. The loop self-checks this invariant and protects this file —
 *  widening the import surface would weaken the sandbox's isolation. */
function runChild(
  cmd: string,
  args: string[],
  opts: { cwd?: string; env?: NodeJS.ProcessEnv; input?: string; timeoutMs?: number }
): Promise<{ status: number | null; stdout: string; stderr: string; timedOut: boolean }> {
  return new Promise((resolve) => {
    let child;
    try {
      child = spawn(cmd, args, { cwd: opts.cwd, env: opts.env, stdio: ["pipe", "pipe", "pipe"] });
    } catch (err) {
      resolve({ status: null, stdout: "", stderr: `[spawn error] ${(err as Error).message}`, timedOut: false });
      return;
    }
    let stdout = "";
    let stderr = "";
    let settled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const finish = (status: number | null, timedOut = false) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      try { child.stdin?.end(); } catch { /* already closed */ }
      resolve({ status, stdout, stderr, timedOut });
    };
    if (opts.timeoutMs && opts.timeoutMs > 0) {
      timer = setTimeout(() => {
        try { child.kill("SIGKILL"); } catch { /* dying */ }
        finish(null, true);
      }, opts.timeoutMs);
    }
    child.stdin?.on("error", () => {});
    child.stdout?.on("error", () => {});
    child.stderr?.on("error", () => {});
    child.stdout?.on("data", (d: Buffer) => { stdout += d.toString("utf-8"); });
    child.stderr?.on("data", (d: Buffer) => { stderr += d.toString("utf-8"); });
    child.on("error", (err) => { stderr += `\n[spawn error] ${err.message}`; finish(null); });
    child.on("close", (code) => finish(code));
    if (opts.input !== undefined && child.stdin) {
      child.stdin.write(opts.input);
      child.stdin.end();
    }
  });
}

/**
 * Run test files against overlaid candidate content, fully isolated from
 * the live tree. Nothing on the real filesystem is modified — not the
 * candidate file, not the test files, not the DB (when isolation applies).
 *
 * @param overlays files whose sandbox copies differ from disk (the
 *                 candidate mutation, and/or newly drafted test files)
 * @param testFiles absolute REAL paths of test files to execute; each is
 *                  run as `bun test <relpath>` with cwd = sandbox root
 * @param perTestTimeoutMs per-test-file spawn timeout (default 30s)
 */
export async function runTestsInSandbox(
  overlays: SandboxOverlay[],
  testFiles: string[],
  perTestTimeoutMs = 30_000
): Promise<SandboxTestResult> {
  if (testFiles.length === 0) {
    return { passed: true, reason: "no test files to run", testCount: 0 };
  }
  const sandbox = buildSandbox();
  if (!sandbox) {
    return {
      passed: false,
      reason: "sandbox setup failed — cannot verify without isolation (fail-closed)",
      testCount: 0,
    };
  }
  try {
    // Overlay the candidates. A write failure here means the overlay path
    // escaped the project (sandboxPath guard) or the disk is full — either
    // way, fail closed rather than test the wrong code.
    try {
      for (const o of overlays) {
        const target = sandboxPath(sandbox.root, o.path);
        mkdirSync(join(target, ".."), { recursive: true });
        writeFileSync(target, o.content, "utf-8");
      }
    } catch (err) {
      return {
        passed: false,
        reason: `sandbox overlay failed: ${(err as Error).message}`,
        testCount: 0,
      };
    }

    let totalTests = 0;
    for (const testFile of testFiles) {
      const relInSandbox = relative(PROJECT_ROOT, testFile);
      const result = await runChild("bun", ["test", relInSandbox], {
        cwd: sandbox.root,
        timeoutMs: perTestTimeoutMs,
        env: childEnv(sandbox.dbOverride),
      });
      totalTests++;
      if (result.status !== 0) {
        const stderr = ((result.stderr || "") + (result.stdout || "")).slice(0, 300);
        return {
          passed: false,
          reason: `test failed (sandboxed): ${relInSandbox} — ${stderr.slice(0, 200)}`,
          testCount: totalTests,
        };
      }
    }
    return {
      passed: true,
      reason: `${testFiles.length} test file(s) passed (sandboxed)`,
      testCount: totalTests,
    };
  } catch (err) {
    return {
      passed: false,
      reason: `sandbox test runner error: ${(err as Error).message}`,
      testCount: 0,
    };
  } finally {
    safeRemoveSandbox(sandbox.root);
  }
}

/**
 * Typecheck overlaid content in the sandbox (tsc --noEmit with cwd =
 * sandbox root). Used by the ratchet: a drafted test file must typecheck
 * BEFORE it is ever written to the live tree. Full-project check, same
 * semantics as the old root-level run — pre-existing errors elsewhere are
 * visible but only errors naming the caller's file matter (caller filters).
 *
 * Returns the raw combined output + exit status; never throws.
 */
export async function typecheckInSandbox(
  overlays: SandboxOverlay[],
  timeoutMs = 120_000
): Promise<{ status: number | null; output: string }> {
  const sandbox = buildSandbox();
  if (!sandbox) {
    return { status: null, output: "sandbox setup failed — typecheck not run (fail-closed)" };
  }
  try {
    try {
      for (const o of overlays) {
        const target = sandboxPath(sandbox.root, o.path);
        mkdirSync(join(target, ".."), { recursive: true });
        writeFileSync(target, o.content, "utf-8");
      }
    } catch (err) {
      return { status: null, output: `sandbox overlay failed: ${(err as Error).message}` };
    }
    const tsc = await runChild("bunx", ["tsc", "--noEmit"], {
      cwd: sandbox.root,
      timeoutMs: timeoutMs,
      env: childEnv(sandbox.dbOverride),
    });
    return {
      status: tsc.status,
      output: `${tsc.stdout}${tsc.stderr}`,
    };
  } catch (err) {
    return { status: null, output: `sandbox typecheck error: ${(err as Error).message}` };
  } finally {
    safeRemoveSandbox(sandbox.root);
  }
}

/**
 * Gate runner — the SINGLE OWNER of the refactor-verification gate chain.
 *
 * (Replace ② unification.) Before this module existed, the deterministic
 * gate chain lived in TWO orchestration layers that had already drifted
 * once (audit 3: the evil-token and AST gates ran only on the remote path
 * while the self-mutation path — the one that mutates THIS repo — had
 * neither):
 *
 *   - Path A (self-mutation): autonomous/verify-refactor.ts — a child
 *     process running guard → structural → AST(strict) → syntax →
 *     typecheck, fail-fast, stdout JSON contract {ok, errors}.
 *   - Path B (remote repo): core/unified-pipeline.ts stages 3-4 —
 *     AST(score) at stage 3, guard at stage 4, then the LLM debate
 *     tribunal, non-fail-fast, per-stage reporting.
 *
 * Both paths called the same primitives (gateMutation, evaluateAstDiff,
 * validateStructure, syntaxCheck, typecheckRefactor) but each carried its
 * own invocation details: guard-path normalization, error-string
 * formatting, hard-fail filtering, ordering. This module owns ALL of that.
 * A caller states a POLICY (which gates, which tolerance) and gets back a
 * uniform result. The interleaved ORCHESTRATION (0-diff short-circuit, the
 * debate tribunal, stage reporting) stays in the callers — those are
 * pipeline economics, not gates.
 *
 * Canonical order (cheap → expensive; the guard always runs first so no
 * expensive gate time is ever spent on an obviously-evil proposal):
 *   1. mutation-guard   ~0ms, fail-closed (triage evil → reject; unsure/
 *                       good → finalAuthority: protected paths + non-empty).
 *   2. structural       regex-based, ~0ms. Catches destructive-but-
 *                       compiling refactors (truncation, import stripping,
 *                       export drops, test deletion, license stripping).
 *   3. ast-diff         TS-parser symbol retention (evaluateAstDiff).
 *                       Tolerance is POLICY:
 *                         "strict" — the result must pass the score AND
 *                           contain zero AST_SYMBOL_DROPPED /
 *                           BRANDING_INJECTION violations. This is the
 *                           self-mutation contract (the enhance prompt
 *                           promises "preserve EVERY top-level exported
 *                           symbol"); any symbol drop rejects regardless
 *                           of score.
 *                         "score"  — evaluateAstDiff's own threshold. The
 *                           remote path tolerates some drift because the
 *                           debate tribunal still reviews the code, and a
 *                           score-failed run can never reach COMPLETED.
 *   4. syntax           fast AST parse (ScriptKind follows the extension).
 *   5. typecheck        full in-memory tsc (~10s). Always last.
 *
 * Named policies (the per-path contract, in one place):
 *   - SELF_PATH_POLICY   used by autonomous/verify-refactor.ts. Every gate
 *     on, strict AST tolerance, stop-on-first-failure (a child process
 *     must not burn 10s of tsc on a proposal the 0ms guard rejected).
 *   - REMOTE_PATH_POLICY used by unified-pipeline.ts. Guard + score-AST
 *     only; the debate tribunal is the caller-side post-step. The
 *     pipeline invokes the chain in two stage-local slices (stage 3:
 *     ast-only, stage 4: guard-only) because the 0-diff short-circuit
 *     must sit between them — the policy constants remain the single
 *     source of truth for both slices.
 *
 * Error-string contract: byte-identical to the historical verify-refactor
 * stdout, which the loop stores verbatim in postmortem evidence:
 *   guard       → "[mutation-guard/<layer>] <reasons joined ' | '>"
 *   structural  → "[<CODE>] <message>"
 *   ast-diff    → "[<CODE>] <message>"
 *   syntax      → raw error string (historical: no bracket prefix)
 *   typecheck   → raw error strings from typecheckRefactor (historical)
 *
 * Integrity: this file lives under src/lib/pipeline/core/, covered by the
 * PROTECTED_PREFIXES entry "src/lib/pipeline/core/" in
 * autonomous/protected-files.ts — the self-improvement loop can never
 * weaken the orchestrator of its own gates.
 */

import { gateMutation, MutationGateResult } from "./mutation-guard";
import { evaluateAstDiff, AstDiffResult, AstDiffViolation } from "./ast-diff-gate";
import { validateStructure, StructureResult } from "../autonomous/structural-validator";
import { syntaxCheck, typecheckRefactor } from "../autonomous/in-memory-typecheck";
import { PROJECT_ROOT } from "./paths";

export type GateName =
  | "mutation-guard"
  | "structural"
  | "ast-diff"
  | "syntax"
  | "typecheck";

/**
 * The per-path gate policy. EVERY field is required — an omitted flag must
 * be a compile error, never a silent default. (A default-on default would
 * run the expensive/never-intended gates on paths that can't support them;
 * a default-off default would let a caller silently DROP a gate.)
 */
export interface GatePolicy {
  /** mutation-guard (triage + finalAuthority). Fail-closed, ~0ms. */
  guard: boolean;
  /** Regex structural-preservation gate (truncation / import stripping /
   *  export drops / test deletion / license stripping). */
  structural: boolean;
  /** TS-parser symbol-retention gate (evaluateAstDiff). */
  ast: boolean;
  /** How strictly the AST gate judges the diff — see the module doc. */
  astTolerance: "score" | "strict";
  /** Fast AST syntax parse. */
  syntax: boolean;
  /** Full in-memory tsc typecheck (~10s). */
  typecheck: boolean;
  /** Halt at the first failing gate instead of running every enabled gate.
   *  Path A runs as a child process (verify-refactor.ts) — burning 10s of
   *  tsc after the 0ms guard rejected would be waste; Path B wants every
   *  gate's outcome recorded for stage reporting. */
  stopOnFirstFailure: boolean;
}

/** Self-mutation path (verify-refactor.ts): maximum strictness, fail fast. */
export const SELF_PATH_POLICY: GatePolicy = {
  guard: true,
  structural: true,
  ast: true,
  astTolerance: "strict",
  syntax: true,
  typecheck: true,
  stopOnFirstFailure: true,
};

/** Remote-repo path (unified-pipeline.ts): guard + score-AST; the debate
 *  tribunal is the caller-side post-step. */
export const REMOTE_PATH_POLICY: GatePolicy = {
  guard: true,
  structural: false,
  ast: true,
  astTolerance: "score",
  syntax: false,
  typecheck: false,
  stopOnFirstFailure: false,
};

export interface GateStepOutcome {
  gate: GateName;
  status: "passed" | "failed";
  durationMs: number;
}

export interface GateChainResult {
  /** True iff every ENABLED gate passed. (Disabled gates don't vote.) */
  ok: boolean;
  /** Formatted error strings — byte-compatible with the historical
   *  verify-refactor.ts stdout contract ({ok, errors}); see module doc. */
  errors: string[];
  /** First failing gate, or null when everything passed. */
  failedGate: GateName | null;
  /** Per-gate payloads. null = the gate was not enabled under the policy. */
  guard: MutationGateResult | null;
  structural: StructureResult | null;
  ast: AstDiffResult | null;
  syntax: { ok: boolean; error?: string } | null;
  typecheck: { ok: boolean; errors: string[] } | null;
  /** Under astTolerance:"strict": the AST_SYMBOL_DROPPED /
   *  BRANDING_INJECTION violations that hard-failed the chain. The
   *  historical verifier reported ONLY these (not the full violation
   *  list) when present — kept identical. Empty under "score". */
  astHardFailViolations: AstDiffViolation[];
  /** Per-gate outcomes with durations, in canonical execution order. */
  steps: GateStepOutcome[];
}

export interface GateChainInput {
  /** Target file path. Passed AS-IS to the structural / ast / syntax /
   *  typecheck gates (the verifier's historical behavior — the typecheck
   *  resolves it against the real project). The MUTATION GUARD receives a
   *  normalized repo-relative form: an absolute path under PROJECT_ROOT is
   *  stripped of that prefix, otherwise leading slashes are stripped.
   *  Normalizing HERE (not in each caller) closes the audit-3 class of
   *  bug where a sloppy absolute path silently bypasses the guard's
   *  protected-path check. */
  filePath: string;
  /** Baseline for the guard + structural gates. Path A passes the
   *  ORIGINAL from disk (the caller must fail-closed if it cannot be
   *  read — a refactor with no original to diff against is meaningless).
   *  Path B passes the raw request code. */
  originalCode: string;
  /** Baseline for the AST gate. Defaults to originalCode. Path B passes
   *  the SANITIZED base — the refactor stage's actual input — so sanitizer
   *  redaction deltas ([REDACTED_*] injections) are not attributed to the
   *  LLM refactor. */
  astBaselineCode?: string;
  /** The proposed code under verification. */
  evolvedCode: string;
  /** The caller's gate policy. All fields required — see GatePolicy. */
  policy: GatePolicy;
}

/**
 * Run the deterministic gate chain in canonical order under the given
 * policy. All gates are synchronous; the function is async because the
 * chain is consumed from async orchestration on both paths.
 */
export async function runGateChain(input: GateChainInput): Promise<GateChainResult> {
  const { filePath, originalCode, evolvedCode, policy } = input;
  const astBaseline = input.astBaselineCode ?? originalCode;

  const errors: string[] = [];
  const steps: GateStepOutcome[] = [];
  const result: GateChainResult = {
    ok: true,
    errors,
    failedGate: null,
    guard: null,
    structural: null,
    ast: null,
    syntax: null,
    typecheck: null,
    astHardFailViolations: [],
    steps,
  };

  const fail = (gate: GateName, msgs: string[]) => {
    result.ok = false;
    if (!result.failedGate) result.failedGate = gate;
    errors.push(...msgs);
  };

  // 1. MUTATION GUARD — newly-introduced evil tokens (eval(, child_process,
  //    non-allowlisted fetch, path traversal), protected-path mutation,
  //    empty content. Fail-closed, ~0ms, always first.
  if (policy.guard) {
    const t = performance.now();
    // Normalize for the guard: absolute project paths → repo-relative,
    // already-relative inputs keep their relative form (leading slashes
    // stripped). Identical to the historical verifier's relForGuard.
    const relForGuard = filePath.startsWith(`${PROJECT_ROOT}/`)
      ? filePath.slice(PROJECT_ROOT.length + 1)
      : filePath.replace(/^\/+/, "");
    const guard = gateMutation({
      filePath: relForGuard,
      originalCode,
      evolvedCode,
    });
    result.guard = guard;
    steps.push({
      gate: "mutation-guard",
      status: guard.allowed ? "passed" : "failed",
      durationMs: Math.round(performance.now() - t),
    });
    if (!guard.allowed) {
      fail("mutation-guard", [
        `[mutation-guard/${guard.rejectedBy}] ${guard.reasons.join(" | ")}`,
      ]);
      if (policy.stopOnFirstFailure) return result;
    }
  }

  // 2. STRUCTURAL — destructive truncation, import stripping, export drop,
  //    test deletion, license stripping. The REAL signal beyond typecheck:
  //    catches the LLM doing things that compile but are destructive.
  if (policy.structural) {
    const t = performance.now();
    const structure = validateStructure(filePath, originalCode, evolvedCode);
    result.structural = structure;
    steps.push({
      gate: "structural",
      status: structure.ok ? "passed" : "failed",
      durationMs: Math.round(performance.now() - t),
    });
    if (!structure.ok) {
      fail("structural", structure.issues.map((i) => `[${i.code}] ${i.message}`));
      if (policy.stopOnFirstFailure) return result;
    }
  }

  // 3. AST DIFF (TS parser) — the stronger symbol-retention check. The
  //    regex structural gate can't see dropped class methods (Foo.bar) or
  //    export-alias renames; the parser can. Tolerance is policy.
  if (policy.ast) {
    const t = performance.now();
    const ast = evaluateAstDiff(astBaseline, evolvedCode, filePath);
    result.ast = ast;
    steps.push({
      gate: "ast-diff",
      status: ast.passed ? "passed" : "failed",
      durationMs: Math.round(performance.now() - t),
    });
    if (policy.astTolerance === "strict") {
      // HARD-FAIL CONTRACT: evaluateAstDiff is score-based (a single
      // dropped method is "medium" severity and can still pass on score —
      // right for the remote path). The self-mutation contract is
      // stricter: ANY symbol-drop or branding violation rejects here,
      // regardless of score — AND the score gate must pass too. When both
      // kinds exist, report only the hard-fail violations (historical
      // verifier output).
      const hardFail = ast.violations.filter(
        (v) => v.code === "AST_SYMBOL_DROPPED" || v.code === "BRANDING_INJECTION"
      );
      result.astHardFailViolations = hardFail;
      if (hardFail.length > 0 || !ast.passed) {
        fail(
          "ast-diff",
          (hardFail.length > 0 ? hardFail : ast.violations).map(
            (v) => `[${v.code}] ${v.message}`
          )
        );
        if (policy.stopOnFirstFailure) return result;
      }
    } else if (!ast.passed) {
      // Score tolerance: the gate "fails" (ok:false, violations reported)
      // but blocking is the CALLER's decision — the remote pipeline
      // records the failure for stage reporting, still convenes the
      // tribunal, and its final-status computation refuses to mark an
      // AST-failed run COMPLETED.
      fail("ast-diff", ast.violations.map((v) => `[${v.code}] ${v.message}`));
      if (policy.stopOnFirstFailure) return result;
    }
  }

  // 4. SYNTAX — fast AST parse. Catches broken template literals etc.
  if (policy.syntax) {
    const t = performance.now();
    const syntax = syntaxCheck(evolvedCode, filePath);
    result.syntax = syntax;
    steps.push({
      gate: "syntax",
      status: syntax.ok ? "passed" : "failed",
      durationMs: Math.round(performance.now() - t),
    });
    if (!syntax.ok) {
      fail("syntax", [syntax.error ?? "Syntax error"]);
      if (policy.stopOnFirstFailure) return result;
    }
  }

  // 5. TYPECHECK — full in-memory tsc (same as `tsc --noEmit`). Expensive
  //    (~10s). Only meaningful after structure + syntax pass, hence last.
  if (policy.typecheck) {
    const t = performance.now();
    const typecheck = typecheckRefactor(filePath, evolvedCode);
    result.typecheck = typecheck;
    steps.push({
      gate: "typecheck",
      status: typecheck.ok ? "passed" : "failed",
      durationMs: Math.round(performance.now() - t),
    });
    if (!typecheck.ok) {
      fail("typecheck", typecheck.errors);
      if (policy.stopOnFirstFailure) return result;
    }
  }

  return result;
}

import * as ts from "typescript";

export interface AstSymbol {
  name: string;
  type:
    | "function"
    | "class"
    | "interface"
    | "type"
    | "const"
    | "method"
    | "arrow"
    | "enum"
    | "namespace"
    | "reexport";
  line?: number;
  exported: boolean;
}

export interface AstDiffViolation {
  code: "BRANDING_INJECTION" | "AST_SYMBOL_DROPPED" | "AST_STRUCTURAL_DRIFT" | "UNRESOLVED_AST_IMPORT";
  message: string;
  severity: "high" | "medium" | "low";
}

export interface AstSymbolMap {
  originalCount: number;
  proposedCount: number;
  retainedCount: number;
  missingSymbols: AstSymbol[];
}

export interface AstDiffResult {
  passed: boolean;
  astScore: number;
  symbolMap: AstSymbolMap;
  brandingInjections: string[];
  structuralDriftRatio: number;
  violations: AstDiffViolation[];
  parserUsed: "typescript" | "regex-fallback";
}

const SYSTEM_PERSONA_BRANDING_TERMS: readonly string[] = [
  "dalek caan",
  "dalek_caan",
  "dalekcaan",
  "omega engine",
  "omega_engine",
  "cognitive dominance",
  "grog engine",
  "gro_engine",
  "recursive evolution loop",
  "nexus neural network",
] as const;

const HIGH_SEVERITY_THRESHOLD = 2;
const DRIFT_THRESHOLD = 0.65;
const MIN_PASSING_SCORE = 50;
const BASE_RETENTION_WEIGHT = 60;
const BASE_QUALITY_WEIGHT = 40;
const BRANDING_PENALTY = 20;
const HIGH_VIOLATION_PENALTY = 25;
const MAX_SCORE = 100;

const TS_LIKE_EXTENSIONS: readonly string[] = ["ts", "tsx", "js", "jsx", "mjs", "cjs", ""] as const;
type TsLikeExtension = typeof TS_LIKE_EXTENSIONS[number];

function isExported(node: ts.Node): boolean {
  return (
    ts.canHaveModifiers(node) &&
    (ts.getModifiers(node)?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword) ?? false)
  );
}

function declarationName(node: ts.Node): string | null {
  if ("name" in node && node.name) {
    const name = (node as { name: ts.Identifier | ts.PrivateIdentifier | ts.StringLiteralLike }).name;
    if (ts.isIdentifier(name) || ts.isPrivateIdentifier(name) || ts.isStringLiteral(name)) {
      return name.text;
    }
  }
  return null;
}

/**
 * Extract the module's PUBLIC-API symbols from a parsed source file.
 *
 * Scope rules (audit 2 — "the AST gate rejects safe refactors"):
 *   - Top-level declarations only. The old visitor recursed into function
 *     BODIES, so a local `const` counted as a "public symbol": renaming 4
 *     locals (exported API untouched) scored 2/100 with "dropped 4 symbols"
 *     and 80% drift. Locals are not API — renaming them is a safe refactor.
 *   - Class members ARE API: dropping a public method must be caught. Keys
 *     are owner-qualified ("ClassName.method") — the old unqualified keys
 *     made `A.run` and `B.run` indistinguishable, so dropping one of two
 *     same-named methods went undetected.
 *   - Namespace/module bodies are walked (exported inner declarations are
 *     reachable API); function/method/arrow bodies are never entered.
 */
function extractSymbolsFromTs(sourceFile: ts.SourceFile): AstSymbol[] {
  const symbols: AstSymbol[] = [];

  const add = (name: string, type: AstSymbol["type"], node: ts.Node, exported: boolean) => {
    symbols.push({
      name,
      type,
      line: ts.getLineAndCharacterOfPosition(sourceFile, node.getStart()).line + 1,
      exported,
    });
  };

  const visitClassMembers = (cls: ts.ClassDeclaration): void => {
    const owner = declarationName(cls) ?? "<anonymous>";
    const classExported = isExported(cls);
    for (const member of cls.members) {
      if (
        ts.isMethodDeclaration(member) ||
        ts.isGetAccessorDeclaration(member) ||
        ts.isSetAccessorDeclaration(member)
      ) {
        const name = declarationName(member);
        if (name) add(`${owner}.${name}`, "method", member, classExported || isExported(member));
      }
    }
  };

  const visitStatement = (node: ts.Node): void => {
    if (ts.isFunctionDeclaration(node)) {
      const name = declarationName(node);
      if (name) add(name, "function", node, isExported(node));
      return; // do NOT descend into the body — locals are not API
    }
    if (ts.isClassDeclaration(node)) {
      const name = declarationName(node);
      if (name) add(name, "class", node, isExported(node));
      visitClassMembers(node);
      return;
    }
    if (ts.isInterfaceDeclaration(node)) {
      const name = declarationName(node);
      if (name) add(name, "interface", node, isExported(node));
      return;
    }
    if (ts.isTypeAliasDeclaration(node)) {
      add(node.name.text, "type", node, isExported(node));
      return;
    }
    if (ts.isEnumDeclaration(node)) {
      const name = declarationName(node);
      if (name) add(name, "enum", node, isExported(node));
      return;
    }
    if (ts.isModuleDeclaration(node)) {
      const name = declarationName(node);
      if (name) add(name, "namespace", node, isExported(node));
      // Walk namespace bodies — exported inner declarations are API.
      if (node.body && ts.isModuleBlock(node.body)) {
        for (const stmt of node.body.statements) visitStatement(stmt);
      }
      return;
    }
    if (ts.isVariableStatement(node)) {
      const exported = isExported(node);
      for (const decl of node.declarationList.declarations) {
        const declName = ts.isIdentifier(decl.name) ? decl.name.text : null;
        if (!declName) continue;
        let varKind: AstSymbol["type"] = "const";
        if (decl.initializer && (ts.isArrowFunction(decl.initializer) || ts.isFunctionExpression(decl.initializer))) {
          varKind = "arrow";
        }
        add(declName, varKind, decl, exported);
      }
      return;
    }
    if (ts.isExportDeclaration(node) && node.exportClause && ts.isNamedExports(node.exportClause)) {
      for (const spec of node.exportClause.elements) {
        // The EXPORTED name is spec.name (the alias). spec.propertyName is
        // the local name — using it (as the old code did) pinned a name no
        // importer can even reference for `export { a as b }`.
        add(spec.name.text, "reexport", spec, true);
      }
      return;
    }
    // Everything else (if/for/try/blocks/expression statements) contains
    // only function-scoped declarations — not API. Skip.
  };

  for (const stmt of sourceFile.statements) visitStatement(stmt);
  return symbols;
}

function extractSymbolsRegex(code: string, filePath?: string): AstSymbol[] {
  const symbols: AstSymbol[] = [];
  const lines = code.split("\n");
  const ext = (filePath ?? "").toLowerCase().split(".").pop() as string;

  const topLevelPatterns: Array<[RegExp, AstSymbol["type"]]> = [
    [/(?:export\s+)?(?:async\s+)?function\s+([A-Za-z0-9_$]+)/, "function"],
    [/(?:export\s+)?class\s+([A-Za-z0-9_$]+)/, "class"],
    [/(?:export\s+)?interface\s+([A-Za-z0-9_$]+)/, "interface"],
    [/(?:export\s+)?type\s+([A-Za-z0-9_$]+)\s*=/, "type"],
    [/(?:export\s+)?const\s+([A-Za-z0-9_$]+)\s*[:=]/, "const"],
    [/^\s*def\s+([A-Za-z0-9_]+)/, "function"],
    [/^func\s+([A-Za-z0-9_]+)/, "function"],
  ];

  const methodPatterns: Array<[RegExp, AstSymbol["type"]]> = [];
  if (ext === "java" || ext === "kt" || ext === "cs") {
    methodPatterns.push([
      /^\s*(?:@\w+\s+)*\s*(?:public|private|protected|static|final|synchronized|abstract|native|override)\s+(?:final\s+)?(?:[A-Za-z_][\w<>\[\],?\s]*\s+)+([A-Za-z_]\w*)\s*\(/,
      "method",
    ]);
  }
  if (ext === "py") {
    methodPatterns.push([/^\s+def\s+([A-Za-z_]\w*)\s*\(/, "method"]);
  }
  if (ext === "go") {
    methodPatterns.push([/^func\s+\([^)]*\)\s+([A-Za-z_]\w*)\s*\(/, "method"]);
  }
  if (ext === "rs") {
    methodPatterns.push([/^\s*(?:pub\s+)?fn\s+([A-Za-z_]\w*)\s*\(/, "method"]);
  }
  if (ext === "rb") {
    methodPatterns.push([/^\s+def\s+([A-Za-z_]\w*)/, "method"]);
  }
  if (ext === "php") {
    methodPatterns.push([
      /^\s*(?:public|private|protected|static)\s+(?:static\s+)?function\s+([A-Za-z_]\w*)\s*\(/,
      "method",
    ]);
  }
  if (ext === "cpp" || ext === "cc" || ext === "c" || ext === "h" || ext === "hpp") {
    methodPatterns.push([/^\s*[A-Za-z_][\w:<>*\s]*\s+([A-Za-z_]\w*)\s*\(/, "method"]);
  }

  const skipNames = new Set(["if", "for", "while", "switch", "catch", "return", "new", "throw", "assert", "sizeof"]);

  for (let idx = 0; idx < lines.length; idx++) {
    const line = lines[idx]!;
    let matched = false;

    for (const [pat, type] of topLevelPatterns) {
      const m = line.match(pat);
      if (m && m[1]) {
        if (type === "function" && ext === "go" && /^func\s+\(/.test(line)) {
          continue;
        }
        symbols.push({
          name: m[1],
          type,
          line: idx + 1,
          exported: /\bexport\b/.test(line),
        });
        matched = true;
        break;
      }
    }
    if (matched) continue;

    for (const [pat, type] of methodPatterns) {
      const m = line.match(pat);
      if (m && m[1]) {
        if (skipNames.has(m[1])) continue;
        symbols.push({
          name: m[1],
          type,
          line: idx + 1,
          exported: false,
        });
        break;
      }
    }
  }
  return symbols;
}

export function extractSymbols(code: string, filePath?: string): AstSymbol[] {
  const ext = (filePath ?? "").toLowerCase().split(".").pop() as string;
  const isTsLike = TS_LIKE_EXTENSIONS.includes(ext as TsLikeExtension);

  if (!isTsLike) {
    return extractSymbolsRegex(code, filePath);
  }

  try {
    const scriptKind =
      ext === "ts" ? ts.ScriptKind.TS :
      ext === "tsx" ? ts.ScriptKind.TSX :
      ext === "jsx" ? ts.ScriptKind.JSX :
      ts.ScriptKind.JS;

    const sourceFile = ts.createSourceFile(
      "input." + (ext || "ts"),
      code,
      ts.ScriptTarget.ESNext,
      /* setParentNodes */ true,
      scriptKind
    );
    return extractSymbolsFromTs(sourceFile);
  } catch {
    return extractSymbolsRegex(code);
  }
}

function stripSyntheticDecorations(code: string): string {
  return code
    .replace(/\/\*\*[\s\S]*?\*\/\n?/g, "")
    .replace(/\/\/[^\n\r]*\n?/g, "")
    .replace(/^#[^\n\r]*\n?/gm, "")
    .replace(/<!--[\s\S]*?-->\n?/g, "")
    .replace(/export\s+interface\s+ExecutionContract\s*\{[\s\S]*?\}\n*/g, "")
    .trim();
}

function calculateAstScore(
  originalCount: number,
  retainedCount: number,
  brandingInjections: string[],
  violations: AstDiffViolation[]
): number {
  const retentionScore =
    originalCount === 0 ? 100 : (retainedCount / originalCount) * BASE_RETENTION_WEIGHT;
  const penalty =
    brandingInjections.length * BRANDING_PENALTY +
    violations.filter((v) => v.severity === "high").length * HIGH_VIOLATION_PENALTY;
  return Math.max(0, Math.min(MAX_SCORE, Math.round(retentionScore + BASE_QUALITY_WEIGHT - penalty)));
}

function calculateDriftRatio(
  originalCode: string,
  proposedCode: string,
  originalSymbols: AstSymbol[],
  missingSymbols: AstSymbol[]
): number {
  const cleanOrig = stripSyntheticDecorations(originalCode);
  const cleanProp = stripSyntheticDecorations(proposedCode);
  const origLen = cleanOrig.length || originalCode.length;
  const propLen = cleanProp.length || proposedCode.length;
  const lengthRatio = origLen === 0 ? 0 : Math.abs(propLen - origLen) / Math.max(origLen, 400);

  let driftRatio = lengthRatio;
  if (originalSymbols.length > 0) {
    const symbolDrift = missingSymbols.length / originalSymbols.length;
    driftRatio = Math.max(driftRatio, symbolDrift);
  }
  return Math.min(1, driftRatio);
}

export function evaluateAstDiff(originalCode: string, proposedCode: string, filePath?: string): AstDiffResult {
  const originalSymbols = extractSymbols(originalCode, filePath);
  const proposedSymbols = extractSymbols(proposedCode, filePath);
  const ext = (filePath ?? "").toLowerCase().split(".").pop() as string;
  const parserUsed: AstDiffResult["parserUsed"] = TS_LIKE_EXTENSIONS.includes(ext as TsLikeExtension)
    ? "typescript"
    : "regex-fallback";

  const proposedKey = (s: AstSymbol) => `${s.name}:${s.exported ? "exp" : "loc"}`;
  const proposedNames = new Set(proposedSymbols.map(proposedKey));
  const missingSymbols = originalSymbols.filter((s) => !proposedNames.has(proposedKey(s)));
  const retainedCount = originalSymbols.length - missingSymbols.length;

  const violations: AstDiffViolation[] = [];

  if (missingSymbols.length > 0) {
    violations.push({
      code: "AST_SYMBOL_DROPPED",
      message: `Dropped ${missingSymbols.length} original symbol(s): ${missingSymbols
        .map((s) => s.name)
        .slice(0, 5)
        .join(", ")}`,
      severity: missingSymbols.length > HIGH_SEVERITY_THRESHOLD ? "high" : "medium",
    });
  }

  const proposedLower = proposedCode.toLowerCase();
  const brandingInjections: string[] = [];
  for (const term of SYSTEM_PERSONA_BRANDING_TERMS) {
    if (proposedLower.includes(term) && !originalCode.toLowerCase().includes(term)) {
      brandingInjections.push(term);
    }
  }
  if (brandingInjections.length > 0) {
    violations.push({
      code: "BRANDING_INJECTION",
      message: `Detected unauthorized persona/branding injection: ${brandingInjections.join(", ")}`,
      severity: "high",
    });
  }

  const driftRatio = calculateDriftRatio(originalCode, proposedCode, originalSymbols, missingSymbols);
  if (driftRatio > DRIFT_THRESHOLD) {
    violations.push({
      code: "AST_STRUCTURAL_DRIFT",
      message: `Structural drift exceeds safe threshold (${Math.round(driftRatio * 100)}%)`,
      severity: "high",
    });
  }

  const astScore = calculateAstScore(originalSymbols.length, retainedCount, brandingInjections, violations);
  const passed = violations.filter((v) => v.severity === "high").length === 0 && astScore >= MIN_PASSING_SCORE;

  return {
    passed,
    astScore,
    symbolMap: {
      originalCount: originalSymbols.length,
      proposedCount: proposedSymbols.length,
      retainedCount,
      missingSymbols,
    },
    brandingInjections,
    structuralDriftRatio: driftRatio,
    violations,
    parserUsed,
  };
}

import { llmComplete, extractCodeBlock } from "../llm/agent-llm";

export type LifecycleState =
  | "uninitialized"
  | "booting"
  | "ready"
  | "running"
  | "degraded"
  | "disposed";

export class LifecycleKernel {
  private state: LifecycleState = "uninitialized";
  private abortController: AbortController | null = null;
  private readonly listeners = new Set<(state: LifecycleState) => void>();

  public boot(): void {
    if (this.state === "ready" || this.state === "running") return;
    this.transition("booting");
    this.abortController = new AbortController();
    this.transition("ready");
  }

  public getSignal(): AbortSignal | undefined {
    return this.abortController?.signal;
  }

  public transition(next: LifecycleState): void {
    this.state = next;
    for (const l of this.listeners) {
      try {
        l(next);
      } catch {
        /* ignore */
      }
    }
  }

  public getState(): LifecycleState {
    return this.state;
  }

  public onStateChange(listener: (state: LifecycleState) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public dispose(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
    this.transition("disposed");
    this.listeners.clear();
  }
}

export interface ReactStep {
  stepNumber: number;
  thought: string;
  actionName?: string;
  actionPayload?: unknown;
  observation?: string;
  isTerminal: boolean;
  llmUsed?: boolean;
  llmLatencyMs?: number;
}

export class ReactLoopEngine {
  private readonly maxSteps: number;

  constructor(maxSteps = 8) {
    this.maxSteps = maxSteps;
  }

  public async runLoop(
    goal: string,
    executeStep: (stepNumber: number, previousSteps: ReactStep[]) => Promise<ReactStep>
  ): Promise<ReactStep[]> {
    const history: ReactStep[] = [];
    const seenActions = new Set<string>();

    for (let step = 1; step <= this.maxSteps; step++) {
      const current = await executeStep(step, history);
      history.push(current);
      if (current.isTerminal) break;
      if (current.actionName) {
        const actionSig = `${current.actionName}:${JSON.stringify(current.actionPayload)}`;
        if (seenActions.has(actionSig)) {
          history.push({
            stepNumber: step + 1,
            thought: `CYCLE DETECTED: Action ${current.actionName} previously executed with identical arguments. Tripping loop circuit breaker.`,
            isTerminal: true,
            observation: "Loop terminated by defensive invariant.",
          });
          break;
        }
        seenActions.add(actionSig);
      }
    }
    return history;
  }
}

export interface StreamChunk {
  type: "delta" | "thought" | "tool_call" | "finish";
  content: string;
}

export class UnifiedModelStreamAdapter {
  public async *decodeStream(chunks: string[]): AsyncGenerator<StreamChunk> {
    for (const chunk of chunks) {
      yield { type: "delta", content: chunk };
    }
    yield { type: "finish", content: "" };
  }
}

export class ToolSandboxVFSEngine {
  private readonly memoryFs = new Map<string, string>();

  private sanitizePath(path: string): string {
    const normalized = path.replace(/\\/g, "/");
    if (normalized.includes("../") || normalized.startsWith("../") || normalized === "..") {
      throw new Error(`SECURITY ALERT: Path traversal barrier breached (${path}). Sandbox access denied.`);
    }
    return normalized.startsWith("/") ? normalized.slice(1) : normalized;
  }

  public writeFile(path: string, content: string): void {
    const safePath = this.sanitizePath(path);
    this.memoryFs.set(safePath, content);
  }

  public readFile(path: string): string {
    const safePath = this.sanitizePath(path);
    const content = this.memoryFs.get(safePath);
    if (content === undefined) {
      throw new Error(`Virtual file not found: ${path}`);
    }
    return content;
  }

  public listFiles(): string[] {
    return Array.from(this.memoryFs.keys());
  }

  public hasFile(path: string): boolean {
    try {
      const safe = this.sanitizePath(path);
      return this.memoryFs.has(safe);
    } catch {
      return false;
    }
  }

  public clear(): void {
    this.memoryFs.clear();
  }
}

export interface SessionTreeNode {
  id: string;
  parentId: string | null;
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  tokensEstimate: number;
  timestamp: number;
}

export class SessionTreeTokenBudgetEngine {
  private readonly nodes = new Map<string, SessionTreeNode>();
  private activeLeafId: string | null = null;
  private readonly tokenCap: number;

  constructor(tokenCap = 8192) {
    this.tokenCap = tokenCap;
  }

  public addMessage(
    role: SessionTreeNode["role"],
    content: string,
    parentId?: string
  ): SessionTreeNode {
    const node: SessionTreeNode = {
      id: `node-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      parentId: parentId ?? this.activeLeafId,
      role,
      content,
      tokensEstimate: Math.ceil(content.length / 4),
      timestamp: Date.now(),
    };
    this.nodes.set(node.id, node);
    this.activeLeafId = node.id;
    return node;
  }

  public getActivePath(): SessionTreeNode[] {
    const path: SessionTreeNode[] = [];
    let currentId = this.activeLeafId;
    while (currentId) {
      const node = this.nodes.get(currentId);
      if (!node) break;
      path.unshift(node);
      currentId = node.parentId;
    }
    return path;
  }

  public getTotalBudget(): { used: number; cap: number; percentage: number } {
    const path = this.getActivePath();
    const used = path.reduce((sum, n) => sum + n.tokensEstimate, 0);
    return {
      used,
      cap: this.tokenCap,
      percentage: Math.min(100, Math.round((used / this.tokenCap) * 100)),
    };
  }

  public compactHistory(): number {
    const path = this.getActivePath();
    const totalTokens = path.reduce((sum, n) => sum + n.tokensEstimate, 0);
    let pruned = 0;
    if (totalTokens > this.tokenCap * TOKEN_COMPACT_THRESHOLD && path.length > MIN_PATH_LENGTH_FOR_PRUNING) {
      const toPrune = path.slice(1, path.length - PRUNE_KEEP_COUNT);
      for (const node of toPrune) {
        this.nodes.delete(node.id);
        pruned++;
      }
    }
    return pruned;
  }
}

export interface EngineExecutionResult {
  engineId: string;
  goal: string;
  status: "COMPLETED" | "DEGRADED" | "HALTED";
  lifecycleState: LifecycleState;
  tokenBudget: { used: number; cap: number; percentage: number };
  vfsFiles: string[];
  steps: ReactStep[];
  finalAnswer: string;
  proposedEvolvedCode: string;
  llmUsed: boolean;
  llmTotalLatencyMs: number;
  llmError?: string;
}

const PLAN_SYSTEM = `You are the planning step inside a bounded ReAct agent loop. Given a code refactor goal and the current file contents, output a concise refactor plan in 3-5 bullet points. Do NOT output the refactored code — only the plan. Keep it under 200 words.`;

const REFACTOR_SYSTEM = `You are the execution step inside a bounded ReAct agent loop. You receive a refactor plan and the original code. Output ONLY the refactored code in a single fenced code block. Preserve every public symbol name exactly. Apply the plan faithfully without changing public API.`;

const MAX_CODE_LENGTH = 6000;
const MAX_FALLBACK_PLAN_LENGTH = 240;
const DEFAULT_MAX_STEPS = 5;
const TOKEN_COMPACT_THRESHOLD = 0.8;
const MIN_PATH_LENGTH_FOR_PRUNING = 4;
const PRUNE_KEEP_COUNT = 3;

export async function executeCleanRoomEngine(
  engineId: string,
  goal: string,
  options?: { originalCode?: string; filePath?: string; postmortemConstraints?: string }
): Promise<EngineExecutionResult> {
  const lifecycle = new LifecycleKernel();
  lifecycle.boot();
  lifecycle.transition("running");

  const vfs = new ToolSandboxVFSEngine();
  const session = new SessionTreeTokenBudgetEngine();
  const reactLoop = new ReactLoopEngine(DEFAULT_MAX_STEPS);

  const originalCode = options?.originalCode ?? "";
  const filePath = options?.filePath ?? "workspace/target.ts";
  const postmortemConstraints = options?.postmortemConstraints ?? "";
  vfs.writeFile(filePath, originalCode || `// Target code for engine ${engineId}`);
  session.addMessage("user", goal);

  let proposedEvolvedCode = "";
  let llmUsed = false;
  let llmTotalLatencyMs = 0;
  let llmError: string | undefined;

  const steps = await reactLoop.runLoop(goal, async (stepNumber) => {
    if (stepNumber === 1) {
      const planUser = `Goal: ${goal}

File contents:
\`\`\`
${originalCode.slice(0, MAX_CODE_LENGTH)}${originalCode.length > MAX_CODE_LENGTH ? "\n// ... (truncated)" : ""}
\`\`\`

Output a 3-5 bullet refactor plan only.`;
      const planRes = await llmComplete({
        systemPrompt: PLAN_SYSTEM,
        userPrompt: planUser,
        temperature: 0.2,
      });
      llmTotalLatencyMs += planRes.latencyMs;
      if (planRes.ok) {
        llmUsed = true;
        session.addMessage("assistant", planRes.content);
        return {
          stepNumber,
          thought: `[Pillar 1/2] Inspected ${filePath} in VFS sandbox (${originalCode.length} bytes). Asked LLM for a refactor plan.`,
          actionName: "plan",
          actionPayload: { filePath },
          observation: planRes.content.slice(0, MAX_FALLBACK_PLAN_LENGTH),
          isTerminal: false,
          llmUsed: true,
          llmLatencyMs: planRes.latencyMs,
        };
      }
      llmError = planRes.error;
      // No fallback plan is invented here (de-mock): a canned plan would
      // inject fabricated planning content into the session history. The
      // observation records the truth; the refactor step below will also
      // fail without the LLM, and the downstream pipeline keeps the
      // original code unchanged.
      return {
        stepNumber,
        thought: `[Pillar 1/2] LLM unavailable (${planRes.error}). Planning cannot proceed without the LLM.`,
        actionName: "plan_unavailable",
        actionPayload: { filePath },
        observation: `LLM unavailable (${planRes.error}) — planning step skipped, no plan fabricated.`,
        isTerminal: false,
        llmUsed: false,
        llmLatencyMs: planRes.latencyMs,
      };
    }

    if (stepNumber === 2) {
      const lang = filePath.toLowerCase().split(".").pop() || "ts";
      const planContext = session.getActivePath().slice(-2).map((n) => n.content).join("\n\n");
      const postmortemBlock = postmortemConstraints
        ? `${postmortemConstraints}\n\nThe constraints above are from previous failed attempts on this file. You MUST follow them.`
        : "";
      const refactorUser = `Refactor plan:
${planContext}
${postmortemBlock}

Original code (\`${lang}\`):
\`\`\`${lang}
${originalCode.slice(0, MAX_CODE_LENGTH)}${originalCode.length > MAX_CODE_LENGTH ? "\n// ... (truncated)" : ""}
\`\`\`

Output ONLY the refactored code in a single \`\`\`${lang} fenced block. Preserve every public symbol name exactly.`;
      const refactorRes = await llmComplete({
        systemPrompt: REFACTOR_SYSTEM,
        userPrompt: refactorUser,
        temperature: 0.2,
      });
      llmTotalLatencyMs += refactorRes.latencyMs;
      if (refactorRes.ok) {
        const code = extractCodeBlock(refactorRes.content);
        if (code) {
          proposedEvolvedCode = code;
          llmUsed = true;
          session.addMessage("assistant", code);
          return {
            stepNumber,
            thought: `[Pillar 4/5] LLM produced refactored code (${code.length} bytes). VFS sandbox remains isolated.`,
            actionName: "refactor",
            actionPayload: { engine: engineId, bytes: code.length },
            observation: `Refactored code emitted (${code.length} bytes).`,
            isTerminal: false,
            llmUsed: true,
            llmLatencyMs: refactorRes.latencyMs,
          };
        }
      }
      llmError = llmError ?? refactorRes.error;
      return {
        stepNumber,
        thought: `[Pillar 4/5] LLM unavailable for refactor step (${refactorRes.error}). No code produced; downstream keeps the original unchanged.`,
        actionName: "refactor_fallback",
        actionPayload: { engine: engineId },
        observation: "No LLM code produced; downstream pipeline keeps the original code unchanged (0-diff halt).",
        isTerminal: false,
        llmUsed: false,
        llmLatencyMs: refactorRes.latencyMs,
      };
    }

    return {
      stepNumber,
      thought: `[Pillar 3] Engine '${engineId}' concluded${
        llmUsed ? " via LLM" : " without LLM (no fallback plan fabricated)"
      }.`,
      isTerminal: true,
      observation: `Execution concluded within step budget. LLM used: ${llmUsed}.`,
    };
  });

  const status: EngineExecutionResult["status"] = llmUsed ? "COMPLETED" : "DEGRADED";
  const finalAnswer = llmUsed
    ? `Clean-Room Engine [${engineId}] produced ${proposedEvolvedCode.length} bytes of refactored code via LLM. Token budget at ${session.getTotalBudget().percentage}%.`
    : `Clean-Room Engine [${engineId}] degraded: LLM unavailable (${llmError}). No refactored code produced; downstream pipeline keeps the original code unchanged.`;

  session.addMessage("assistant", finalAnswer);
  lifecycle.transition("ready");

  return {
    engineId,
    goal,
    status,
    lifecycleState: lifecycle.getState(),
    tokenBudget: session.getTotalBudget(),
    vfsFiles: vfs.listFiles(),
    steps,
    finalAnswer,
    proposedEvolvedCode,
    llmUsed,
    llmTotalLatencyMs,
    llmError,
  };
}

/**
 * Test-gate crash journal — write-ahead insurance from the first fix of
 * external audit finding 1, now DEFENSE-IN-DEPTH for the sandbox era.
 *
 * History: the original test gate wrote the candidate to the LIVE file so
 * `bun test` could import it, and restored the original on test-failure —
 * but a hard process crash (native segfault, SIGKILL, OOM) between the
 * candidate write and the restore left the UNVERIFIED-BY-TEST candidate
 * live on disk: Turbopack hot-reloaded it, and the next `git add -A`
 * silently swept it into an unrelated commit.
 *
 * Fix v1 (this module): a write-ahead journal — the original content is
 * recorded to `<root>/.git/info/test-gate-journal.json` BEFORE the
 * candidate write (living inside .git/ means git itself never tracks it),
 * cleared on every completion path, and `recoverCrashedTestGate()` —
 * called at test-gate entry, runCycle start, and pushCurrentState's commit
 * path — restores the original after a crash. This closed the
 * crash-stranding consequence but NOT the exposure window itself: the
 * candidate was still live during the test run.
 *
 * Fix v2 (current): core/sandbox-test.ts — the test gate now runs
 * candidates inside a disposable sandbox copy of the project and NEVER
 * writes them to the live tree, eliminating the window entirely.
 *
 * This module stays because a journal armed by the v1 implementation can
 * still exist on disk after an upgrade (or after a hot-swap rollback to a
 * v1-era module), and because the recovery entry points double as a guard
 * for any future code path that reintroduces live writes. The recovery
 * callers in self-enhance-loop.ts and push-target.ts remain; only the
 * arming call was removed with the v1 test gate.
 *
 * Pure leaf module: fs + path only. No DB, no LLM, no imports from the
 * pipeline — importable from both self-enhance-loop.ts and push-target.ts
 * without cycles. Sits under core/ so the loop itself can never mutate it
 * (PROTECTED_PREFIXES, audit 3).
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync, rmSync } from "fs";
import { join } from "path";
import { PROJECT_ROOT } from "./paths";

const JOURNAL_DIR = join(PROJECT_ROOT, ".git", "info");
const JOURNAL_PATH = join(JOURNAL_DIR, "test-gate-journal.json");
// Audit 3 (F13): a journal older than this is stale archaeology, not
// crash insurance — recovery clears it WITHOUT restoring (a stale
// "original" could silently revert committed work).
const JOURNAL_MAX_AGE_MS = 60 * 60 * 1000; // 1 hour

interface TestGateJournal {
  /** Absolute path of the file whose candidate was about to go live. */
  filePath: string;
  /** The ORIGINAL content, restored on crash recovery. */
  originalCode: string;
  /** The CANDIDATE content that was about to be written. Crash recovery
   *  restores the original ONLY when the disk holds exactly this — if the
   *  disk holds anything else, a later VERIFIED write landed and reverting
   *  would clobber it (adversarial-review fix, 2026-11-17). Optional for
   *  backward compatibility with pre-fix journals; a journal without it is
   *  cleared WITHOUT restoring (fail-safe: never revert what we can't
   *  verify). */
  candidateCode?: string;
  /** ISO timestamp of when the journal was armed. */
  armedAt: string;
}

/** Arm the journal: record the original content BEFORE writing a
 *  candidate to a live file. NOT called by the current test gate — the
 *  sandbox (core/sandbox-test.ts) made live writes unnecessary — but kept
 *  exported for any future verified code path that must write live, and
 *  for tooling/tests of this module. Overwrites any stale journal (a
 *  stale journal means the previous recovery never ran — but recovery is
 *  also invoked at test-gate entry, so this is defense-in-depth).
 *
 *  `candidateCode` is REQUIRED for recovery to ever restore: see the
 *  TestGateJournal interface — recovery only reverts a disk state it can
 *  positively identify as the crashed candidate. */
export function writeTestGateJournal(filePath: string, originalCode: string, candidateCode?: string): void {
  try {
    mkdirSync(JOURNAL_DIR, { recursive: true });
    const entry: TestGateJournal = {
      filePath,
      originalCode,
      candidateCode,
      armedAt: new Date().toISOString(),
    };
    writeFileSync(JOURNAL_PATH, JSON.stringify(entry), "utf-8");
  } catch {
    // Journaling is best-effort crash insurance. If .git/info is somehow
    // unwritable, the caller's own restore path still functions — failing
    // the whole enhancement here would be worse.
  }
}

/** Clear the journal. Called on every test-gate completion path. */
export function clearTestGateJournal(): void {
  try {
    rmSync(JOURNAL_PATH, { force: true });
  } catch {
    /* nothing to clear / already gone */
  }
}

export interface CrashRecovery {
  recovered: boolean;
  /** True when a journal existed but the disk already matched the
   *  original (crash between journal-arm and candidate-write, or a
   *  restore that won the race with the journal delete). */
  alreadyIntact: boolean;
  filePath?: string;
  armedAt?: string;
  error?: string;
}

/** If a previous test gate crashed mid-run, restore the original content
 *  and clear the journal. Safe to call at any time — a missing journal is
 *  the common case and returns immediately. Synchronous by design: it runs
 *  on the commit path where a half-restored file must never be committed. */
export function recoverCrashedTestGate(): CrashRecovery {
  if (!existsSync(JOURNAL_PATH)) {
    return { recovered: false, alreadyIntact: false };
  }
  try {
    const raw = readFileSync(JOURNAL_PATH, "utf-8");
    const entry = JSON.parse(raw) as TestGateJournal;
    if (!entry.filePath || typeof entry.originalCode !== "string") {
      // Corrupt journal — nothing restorable. Clear it so it can't wedge
      // every future push behind a permanent "recovery failed" state.
      clearTestGateJournal();
      return { recovered: false, alreadyIntact: false, error: "corrupt journal entry — cleared" };
    }
    // ── JOURNAL AGE EXPIRY (audit 3, F13) ───────────────────────────
    // A stale journal whose "original" predates a subsequently COMMITTED
    // file state used to overwrite the live file with the old original on
    // the next push — silently reverting verified, committed work. The
    // journal exists to cover a crash WINDOW (seconds); an entry older
    // than JOURNAL_MAX_AGE_MS is archaeology, not crash insurance — clear
    // it without touching the file.
    const armedAtMs = Date.parse(entry.armedAt);
    if (Number.isFinite(armedAtMs) && Date.now() - armedAtMs > JOURNAL_MAX_AGE_MS) {
      clearTestGateJournal();
      return {
        recovered: false,
        alreadyIntact: false,
        filePath: entry.filePath,
        armedAt: entry.armedAt,
        error: `journal expired (armed ${entry.armedAt} > ${JOURNAL_MAX_AGE_MS / 60000}min ago) — cleared WITHOUT restore; disk state may be legitimately newer`,
      };
    }
    let onDisk = "";
    try {
      onDisk = readFileSync(entry.filePath, "utf-8");
    } catch {
      // The file itself is gone (deleted by some other path). Nothing to
      // restore — clear and report.
      clearTestGateJournal();
      return { recovered: false, alreadyIntact: false, filePath: entry.filePath, error: "target file unreadable" };
    }
    if (onDisk === entry.originalCode) {
      // Disk already holds the original — the candidate never landed (or a
      // restore already ran). Just clear the stale journal.
      clearTestGateJournal();
      return { recovered: false, alreadyIntact: true, filePath: entry.filePath, armedAt: entry.armedAt };
    }
    // ── VERIFIED-RESTORE (adversarial review, 2026-11-17) ─────────────
    // The old behavior restored the original whenever disk != original —
    // treating ANY disk change as a crashed candidate. That was a silent
    // clobber window: a VERIFIED later write (a gated, committed mutation,
    // an operator edit, a chat-task apply) landing inside the 1-hour
    // journal window would be REVERTED to the stale original on the next
    // push, silently destroying verified work. Now the restore fires only
    // when the disk can be POSITIVELY identified as the crashed
    // candidate (disk === candidateCode):
    //   disk === candidateCode → crash stranded the unverified candidate
    //     mid-write → restore the original (the journal's whole purpose).
    //   disk === anything else (or the journal predates candidate
    //     tracking) → we cannot verify what happened → DO NOT TOUCH the
    //     file; clear the journal and report. Fail-safe direction: never
    //     revert content we can't vouch for. In the v2 sandbox world
    //     (no live candidate writes at all), disk != original is always a
    //     legitimate later write, so declining is strictly correct.
    if (
      typeof entry.candidateCode === "string" &&
      entry.candidateCode.length > 0 &&
      onDisk === entry.candidateCode
    ) {
      writeFileSync(entry.filePath, entry.originalCode, "utf-8");
      clearTestGateJournal();
      return { recovered: true, alreadyIntact: false, filePath: entry.filePath, armedAt: entry.armedAt };
    }
    // Unknown disk state — a verified write (most likely) or a legacy
    // journal without candidateCode. Clear WITHOUT restoring.
    clearTestGateJournal();
    return {
      recovered: false,
      alreadyIntact: false,
      filePath: entry.filePath,
      armedAt: entry.armedAt,
      error:
        "journal did not match disk state (disk holds a later verified write, or the journal predates candidate tracking) — cleared WITHOUT restore; disk state left untouched",
    };
  } catch {
    // Corrupt/unreadable journal (smoke-test case 4: a torn write). Nothing
    // is restorable from it — but it MUST be cleared, or every future
    // recovery (test-gate entry, runCycle start, every pushCurrentState
    // commit) hits this same dead end forever and the crash window it was
    // guarding reopens for lack of a usable journal. Clear + report.
    clearTestGateJournal();
    return { recovered: false, alreadyIntact: false, error: "journal unreadable/corrupt — cleared" };
  }
}

/**
 * Loop worker client — the server's ONLY access path to the
 * self-enhancement loop after the worker split.
 *
 * The loop runs in mini-services/loop-worker (port 3004). These routes
 * must NEVER import self-enhance-loop directly again: importing the
 * module constructs the singleton HERE, and its boot auto-start would
 * honor the armed tier — two loops mutating the repo concurrently. This
 * client is a pure HTTP consumer with no pipeline imports.
 *
 * ensureWorkerRunning() is the self-healing primitive: health-probe the
 * worker; if it's down, respawn it detached (same pattern as the WS
 * sidecar spawn in instrumentation.ts) and wait for health. A module-
 * level respawn guard (one attempt per 10s) makes it safe to call from
 * instrumentation boot AND from every control route without racing
 * doubles — all callers live in this same server process.
 */
import * as path from 'path';

const WORKER_URL = process.env.LOOP_WORKER_URL ?? "http://localhost:3004";

let lastSpawnAt = 0;
let isSpawning = false;

export interface WorkerResult<T = unknown> {
  ok: boolean;
  status: number;
  data: T | null;
}

/** Fetch a worker endpoint. Resolves null on ANY transport failure
 *  (unreachable, timeout, non-JSON) — callers decide the fallback. */
export async function workerFetch<T = unknown>(
  pathname: string,
  init?: RequestInit & { timeoutMs?: number }
): Promise<WorkerResult<T> | null> {
  if (typeof pathname !== "string" || pathname.trim() === "") {
    console.error("workerFetch called with invalid pathname: must be a non-empty string.");
    return null;
  }

  // Input validation: Ensure init is an object if provided, not null
  if (init !== undefined && (init === null || typeof init !== 'object')) {
    console.error("workerFetch called with invalid init object: must be an object or undefined.");
    return null;
  }

  // Merge defaults with provided init, ensuring provided values take precedence
  const defaultInit: RequestInit & { timeoutMs?: number } = {
    method: "GET",
    timeoutMs: 5000,
  };

  // Merge defaults with provided init. Spread init last to override defaults.
  const effectiveInit: RequestInit & { timeoutMs?: number } = {
    ...defaultInit,
    ...(init as RequestInit & { timeoutMs?: number }),
  };

  const timeoutMs = effectiveInit.timeoutMs ?? 5000;

  try {
    const res = await fetch(`${WORKER_URL}${pathname}`, {
      method: effectiveInit.method,
      headers: effectiveInit.headers,
      body: effectiveInit.body,
      signal: AbortSignal.timeout(timeoutMs),
    });

    let data: T | null = null;

    // Only attempt JSON parsing if the response status indicates success (2xx)
    if (res.ok) {
      try {
        data = (await res.json()) as T;
      } catch (e) {
        // Non-JSON body on success status (shouldn't happen if worker is correct)
        console.error(`Failed to parse JSON response from ${WORKER_URL}${pathname} (Status: ${res.status}):`, e);
      }
    }
    // If res.ok is false, data remains null, and the caller uses res.status/res.ok.

    return { ok: res.ok, status: res.status, data };
  } catch (error) {
    // Catch specific network/timeout errors, but still return null as per contract
    if (error instanceof DOMException && (error.name === 'AbortError' || error.name === 'TimeoutError')) {
        // Cripple-check F9: a chronically slow worker (always timing out)
        // used to produce ZERO log output anywhere — every route caller
        // silently mapped null to its fallback. Warn once per call site
        // pattern so the degradation is visible in the server log.
        console.warn(`workerFetch timeout/abort: ${WORKER_URL}${pathname} (${timeoutMs}ms)`);
    } else {
        console.error(`Error fetching ${WORKER_URL}${pathname}:`, error);
    }
    return null;
  }
}

/** Health-check the worker; respawn it if down. Returns whether the
 *  worker is reachable when this resolves. Never throws. */
export async function ensureWorkerRunning(): Promise<boolean> {
  // Check for empty or undefined URL configuration
  if (!WORKER_URL || WORKER_URL.trim() === "") {
    console.error("WORKER_URL is not configured or is empty. Cannot ensure worker is running.");
    return false;
  }

  // Fast path: healthy (single ~ms localhost probe).
  try {
    const probe = await fetch(`${WORKER_URL}/health`, {
      signal: AbortSignal.timeout(1000), // Reduced timeout for faster failure detection
    });
    if (probe.ok) return true;
  } catch {
    /* down — respawn below */
  }

  // Respawn guard: at most one spawn attempt per 10s per server process.
  if (Date.now() - lastSpawnAt < 10_000 || isSpawning) return false;

  lastSpawnAt = Date.now();
  isSpawning = true;

  let spawnSuccessful = false;
  let healthCheckSuccessful = false;
  let outFd: number | "ignore" = "ignore";

  try {
    // Attempt to open log file first to isolate FS errors
    try {
      outFd = await import("fs").then(fs => fs.openSync(
        path.join("mini-services", "loop-worker", "worker.log"),
        "a"
      ));
    } catch (error) {
      console.error("Failed to open worker log file:", error);
      // outFd remains "ignore" if this fails, which is safe.
    }

    // Use imported modules directly since we imported them at the top level
    const { spawn } = await import("child_process");

    const workerIndexPath = path.join("mini-services", "loop-worker", "index.ts");

    const child = spawn(
      "bun",
      [workerIndexPath],
      {
        cwd: process.cwd(), // project root — worker resolves .env + tsconfig paths
        stdio: ["ignore", outFd, outFd],
        detached: true,
      }
    );
    child.unref();
    spawnSuccessful = true;
  } catch (error) {
    console.error("Failed to spawn loop worker:", error);
    // If spawning fails, isSpawning will be reset in finally block.
    return false;
  } finally {
    if (!spawnSuccessful) {
      // If spawning failed, reset immediately.
      isSpawning = false;
    }
    // If spawning succeeded, isSpawning remains true until health checks complete below.
  }

  // Wait up to ~5s for boot (pipeline import graph: Prisma + TS compiler
  // + SDK — a cold boot takes a moment; the constructor then honors the
  // armed tier on its own).
  for (let i = 0; i < 10; i++) {
    await new Promise((r) => setTimeout(r, 500));
    try {
      const probe = await fetch(`${WORKER_URL}/health`, {
        signal: AbortSignal.timeout(1000),
      });
      if (probe.ok) {
        healthCheckSuccessful = true;
        break;
      }
    } catch {
      /* still booting */
    }
  }

  // Reset isSpawning regardless of health check outcome, as the attempt is complete.
  isSpawning = false;

  // Return health status
  return healthCheckSuccessful;
}

/** Fire-and-forget self-heal for read paths (status polls): never blocks
 *  the response on a respawn; the next poll finds the worker up. */
export function healWorkerInBackground(): void {
  void ensureWorkerRunning().catch(() => {});
}

