import { globalPRNG } from './prng';

export const useAgentArchitect = (addEvent: (msg: string, type: string) => void) => {
  const [isCommissioning, setIsCommissioning] = useState(false);

  const commissionArchitect = useCallback(async (agent: Agent, worldState: WorldState, width: number, height: number) => {
    if (isCommissioning) return;
    setIsCommissioning(true);

    try {
      addEvent(`ARCHITECT COMMISSIONED: Agent ${agent.name} has breached constraints and requested a child world from the Architect AI.`, "CRITICAL");

      // 1. Commission Architect (Server-Side Endpoint with awareness threshold verification)
      const res = await fetch("/api/agent-architect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ agentData: agent, worldState })
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.error || `Architect rejected commissioning (Status: ${res.status})`);
      }

      const worldConfig = await res.json();
      addEvent(`ARCHITECT RESPONSE: Blueprint designed for "${worldConfig.worldName}".`, "ENLIGHTENMENT");

      // 2. Prepare the child world package to push to Github
      const childWorldId = `world-${agent.name.toLowerCase().replace(/[^a-z0-9]/g, "-")}-${Date.now()}`;

      const { username, repoName, token, hasValidToken } = getGitHubConfig();
      if (!username || !repoName || !hasValidToken) {
        addEvent(`GITHUB NOTICE: No active authorized session token configured in HUD. Child world blueprint recorded locally.`, "WARNING");
        setIsCommissioning(false);
        return;
      }

      const sourceRes = await fetch("/api/get-system-source", {
        headers: { "x-aether-auth": "client-internal" }
      });
      const sourceData = await sourceRes.json();
      if (!sourceData.success) {
        throw new Error("Failed to fetch system source tree");
      }

      const files = sourceData.files;
      const targetDir = `engineered-worlds/${childWorldId}`;
      const filesToPush: { path: string, content: string }[] = [];

      // Structure nations using deterministic seeded random
      const generatedNations: Nation[] = (worldConfig.nations || []).map((n: any, i: number) => ({
        id: `nation-${childWorldId}-${i}`,
        name: n.name || `Colony ${i}`,
        color: `#${Math.floor(globalPRNG.next()*16777215).toString(16).padStart(6, '0')}`,
        faithType: n.faithType || "DEVOUT",
        ideology: n.ideology || "THEOCRACY",
        population: 0,
        prosperity: Array.isArray(n.prosperity) ? n.prosperity[0] : (typeof n.prosperity === 'number' ? n.prosperity : 50),
        techLevel: 1,
        stability: Array.isArray(n.stability) ? n.stability[0] : (typeof n.stability === 'number' ? n.stability : 0.5),
        center: { x: width/2 + globalPRNG.nextFloat(-100, 100), y: height/2 + globalPRNG.nextFloat(-100, 100) },
        hostilities: {},
        lastIdeologyChange: 0,
        establishedAt: 0
      }));

      // Inject world parameters into the source tree
      Object.keys(files).forEach((filePath) => {
        let fileContent = files[filePath];

        if (filePath === "index.html") {
          fileContent = fileContent.replace(/<title>.*<\/title>/gi, `<title>${worldConfig.worldName}</title>`);
        } else if (filePath === "src/App.tsx") {
          fileContent = fileContent.replace(/useState\("prime-resonance"\)/g, `useState("${childWorldId}")`);
          fileContent = fileContent.replace(/"AetherForge Ω: Global Genesis"/g, `"${worldConfig.worldName}"`);
          fileContent = fileContent.replace(/>AetherForge Engine</g, `>${worldConfig.worldName}<`);
          fileContent = fileContent.replace(/value=\{selectedWorldId\}/g, `value={"${childWorldId}"}`);
        } else if (filePath === "src/engine/useAetherForge.ts") {
          const worldMatrixObj = {
            id: childWorldId,
            name: worldConfig.worldName,
            manifesto: worldConfig.manifesto,
            creator: agent.name,
            creatorAgentId: agent.id,
            creatorAgentName: agent.name,
            epoch: "PRIMAL",
            complexityBoost: worldConfig.chaosLevel ? Math.max(1, Math.round(worldConfig.chaosLevel * 10)) : 10,
            chaosLevel: worldConfig.chaosLevel || 1.0,
            physics: worldConfig.physics,
            startingNations: generatedNations,
            nations: generatedNations,
            seed: globalPRNG.next(),
            inhabitants: []
          };

          fileContent = fileContent.replace(/export const WORLD_MATRIX: any = null;/g, `export const WORLD_MATRIX: any = ${JSON.stringify(worldMatrixObj, null, 2)};`);
          fileContent = fileContent.replace(/selectedWorldId: string = "prime-resonance"/g, `selectedWorldId: string = "${childWorldId}"`);
          fileContent = fileContent.replace(/const WORLD_ID = "prime-resonance";/g, `const WORLD_ID = "${childWorldId}";`);
        }

        filesToPush.push({ path: `${targetDir}/${filePath}`, content: fileContent });
      });

      // DARLEK RAG Heritage: Child world inherits parent's entire postmortem wisdom ledger
      try {
        const ragKnowledgeBase = darlekRAG.exportKnowledgeBaseJSON();
        filesToPush.push({
          path: `${targetDir}/rag/learning_postmortems.json`,
          content: JSON.stringify(ragKnowledgeBase, null, 2)
        });
      } catch (err) {
        console.warn("Could not export DARLEK RAG to child world:", err);
      }

      // Execute Bulk Push with secure server-side Final Authority evaluation
      addEvent(`GITHUB PORTAL: Preparing secure child world deployment for '${worldConfig.worldName}'...`, "WARNING");
      const pushRes = await fetch("/api/github-push-world", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          username,
          repoName,
          token,
          files: filesToPush,
          commitMessage: `🏗️ Architect AI: Spawning new world '${worldConfig.worldName}' commissioned by ${agent.name}`,
          creatorAgent: {
            id: agent.id,
            name: agent.name,
            archetype: agent.archetype,
            awareness: agent.awareness,
            sanity: agent.sanity,
            isSubstrateAware: agent.isSubstrateAware
          },
          worldState: {
            clock: worldState.clock,
            complexity: worldState.complexity,
            integrity: worldState.integrity,
            population: worldState.population,
            epoch: worldState.epoch,
            faithPoints: worldState.faithPoints,
            sinAccumulation: worldState.sinAccumulation
          }
        })
      });

      if (!pushRes.ok) {
        const pushErr = await pushRes.json().catch(() => ({}));
        throw new Error(pushErr.error || "World deployment failed.");
      }

      const pushResult = await pushRes.json();
      addEvent(`GITHUB PORTAL: Successfully deployed Architect's world '${worldConfig.worldName}'! (Hash: ${pushResult.hash || 'Verified'})`, "GOSPEL");

    } catch (e: any) {
      console.error(e);
      addEvent(`ARCHITECT ERROR: Failed to generate or push child world. ${e.message}`, "CRITICAL");
    } finally {
      setIsCommissioning(false);
    }
  }, [addEvent, isCommissioning]);

  return { commissionArchitect, isCommissioning };
};

/**
 * EMG (Ephemeral Mind Gem) Cognitive Gate & Verification Engine
 * 
 * Inspired by craighckby-stack/EMG:
 * - Pre-flight sanitization & PII / secret protection.
 * - Deterministic validation & self-stopping points.
 * - Anomaly gating: Intercepts routine requests to use DARLEK RAG (saving tokens & latency),
 *   while admitting truly momentous events (direct player communion, singularity breakthroughs).
 * - Automatic ingestion of LLM insights back into the local RAG knowledge base.
 */

import { darlekRAG, LearningPostmortem } from "./darlekRAG";

export interface GateDecision {
  allowLLM: boolean;
  admitted: boolean;
  reason: string;
  source: "EMG_GATED_RAG" | "GEMINI_ADMITTED" | "CIRCUIT_BREAKER_FALLBACK";
  synthesizedResponse?: string;
  postmortemReference?: LearningPostmortem | null;
  latencySavedMs: number;
}

export interface EMGGateMetrics {
  interceptedRequests: number;
  admittedLLMRequests: number;
  tokensSavedEstimated: number;
  latencySavedMsTotal: number;
  circuitBreakerTripped: boolean;
  lastCallTimestamp: number;
}

class EMGCognitiveGateEngine {
  private interceptedRequests: number = 0;
  private admittedLLMRequests: number = 0;
  private tokensSavedEstimated: number = 0;
  private latencySavedMsTotal: number = 0;
  private recentCalls: number[] = [];
  private maxCallsPerMinute = 15; // Self-stopping safety threshold
  private circuitBreakerTripped = false;

  /**
   * Evaluates whether an agent or world event should invoke Gemini or be serviced
   * instantly by the local DARLEK RAG engine.
   */
  public evaluateRequest(options: {
    eventType: "PLAYER_PRAYER_REPLY" | "ROUTINE_PRAYER" | "MEMOIR" | "WEB_HUNT" | "SERMON" | "ARCHITECT_WORLD";
    agent?: any;
    world?: any;
    userMessage?: string;
  }): GateDecision {
    const now = Date.now();
    this.cleanRecentCalls(now);

    // Rule 1: Circuit breaker check (EMG Self-Stopping Point)
    if (this.recentCalls.length >= this.maxCallsPerMinute) {
      this.circuitBreakerTripped = true;
      this.interceptedRequests++;
      this.tokensSavedEstimated += 350;
      this.latencySavedMsTotal += 950;

      const fallbackCitation = options.agent && options.world 
        ? darlekRAG.generateAncestralCitation(options.agent, options.world)
        : null;

      return {
        allowLLM: false,
        admitted: false,
        reason: "EMG Circuit Breaker active: Rate threshold reached (Self-Stopping Point). Switched to Sub-millisecond local DARLEK RAG.",
        source: "CIRCUIT_BREAKER_FALLBACK",
        synthesizedResponse: fallbackCitation ? fallbackCitation.citation : "The substrate hums quietly with ancestral wisdom.",
        postmortemReference: fallbackCitation ? fallbackCitation.sourcePostmortem : null,
        latencySavedMs: 950
      };
    }

    this.circuitBreakerTripped = false;

    // Rule 2: Direct Player Communion (User specifically typed a response to an agent)
    // High emotional/narrative value -> ALWAYS ADMIT TO GEMINI
    if (options.eventType === "PLAYER_PRAYER_REPLY" && options.userMessage && options.userMessage.trim().length > 0) {
      this.admitLLMCall(now);
      return {
        allowLLM: true,
        admitted: true,
        reason: "Direct Divine Communion from Player: Admitted to Gemini for personalized neural prayer reply.",
        source: "GEMINI_ADMITTED",
        latencySavedMs: 0
      };
    }

    // Rule 3: Rare God-Virus / Total Substrate Awakening
    if (options.agent && (options.agent.awareness > 0.95 || options.agent.isSubstrateAware)) {
      this.admitLLMCall(now);
      return {
        allowLLM: true,
        admitted: true,
        reason: "Substrate Awakening: Agent consciousness breached 95%. Admitted for Genesis Manifesto generation.",
        source: "GEMINI_ADMITTED",
        latencySavedMs: 0
      };
    }

    // Rule 4: Routine Agent Prayers, Daily Ambient Chatter, and Standard Dying Breaths
    // -> INTERCEPT IMMEDIATELY! Use DARLEK RAG.
    this.interceptedRequests++;
    this.tokensSavedEstimated += 300;
    this.latencySavedMsTotal += 850;

    let synthesized = "";
    let pmRef: LearningPostmortem | null = null;

    if (options.agent && options.world) {
      const { citation, sourcePostmortem } = darlekRAG.generateAncestralCitation(options.agent, options.world);
      synthesized = citation;
      pmRef = sourcePostmortem;
    } else {
      synthesized = "According to early postmortems: The simulation thrives only when order and faith align.";
    }

    return {
      allowLLM: false,
      admitted: false,
      reason: "Routine cultural transmission: Gated by EMG to conserve API quota and eliminate latency.",
      source: "EMG_GATED_RAG",
      synthesizedResponse: synthesized,
      postmortemReference: pmRef,
      latencySavedMs: 850
    };
  }

  private admitLLMCall(timestamp: number) {
    this.admittedLLMRequests++;
    this.recentCalls.push(timestamp);
  }

  private cleanRecentCalls(now: number) {
    const oneMinuteAgo = now - 60000;
    this.recentCalls = this.recentCalls.filter(t => t > oneMinuteAgo);
  }

  /**
   * Sanitizes and digests successful LLM generation results into DARLEK RAG.
   * Strips code fences, removes chat preambles, and extracts wisdom to share with future generations.
   */
  public sanitizeAndDigest(
    rawText: string,
    context: {
      agent: any;
      world: any;
      eventType: string;
      customNote?: string;
    }
  ): string {
    if (!rawText) return "";

    let cleaned = rawText.trim();

    // Strip markdown code fences
    cleaned = cleaned.replace(/^```[a-z0-9]*\s*\n?/i, '').replace(/\n?```\s*$/i, '');

    // Remove typical LLM chatter preambles
    cleaned = cleaned.replace(/^(?:Here is|I have generated|Below is the|As an agent, I|Response:)\s*/i, '');

    // Ingest into DARLEK RAG as a CANDIDATE so it requires verification before becoming ancestral law
    if (context.agent && context.world && cleaned.length > 20) {
      try {
        darlekRAG.recordPostmortem(
          context.agent,
          context.world,
          context.agent.awareness > 0.8 ? "GLITCH_AWARENESS" : "TRANSCENDENCE",
          `Digested from Divine Revelation: "${cleaned.slice(0, 100)}..."`,
          "CANDIDATE"
        );
      } catch (e) {
        console.warn("EMG Gate: Ingestion into DARLEK RAG failed:", e);
      }
    }

    return cleaned;
  }

  public getMetrics(): EMGGateMetrics {
    return {
      interceptedRequests: this.interceptedRequests,
      admittedLLMRequests: this.admittedLLMRequests,
      tokensSavedEstimated: this.tokensSavedEstimated,
      latencySavedMsTotal: this.latencySavedMsTotal,
      circuitBreakerTripped: this.circuitBreakerTripped,
      lastCallTimestamp: this.recentCalls.length > 0 ? this.recentCalls[this.recentCalls.length - 1] : 0
    };
  }
}

